#include <torch/extension.h>
#include <hip/hip_runtime.h>
#include <ATen/hip/HIPContext.h>

__global__ void bmm_kernel(const float* A, const float* B, float* out, int N, int M, int K, int L) {
    int n = blockIdx.z;
    int m = blockIdx.y * blockDim.y + threadIdx.y;
    int l = blockIdx.x * blockDim.x + threadIdx.x;

    if (m < M && l < L) {
        float sum = 0.0f;
        for (int k = 0; k < K; k++) {
            sum += A[n * M * K + m * K + k] * B[k * L + l];
        }
        out[n * M * L + m * L + l] = sum;
    }
}

torch::Tensor bmm_rocm(torch::Tensor A, torch::Tensor B) {
    int N = A.size(0);
    int M = A.size(1);
    int K = A.size(2);
    int L = B.size(1);

    torch::Tensor out = torch::zeros({N, M, L}, A.options());

    dim3 threads(16, 16);
    dim3 blocks((L + threads.x - 1) / threads.x, (M + threads.y - 1) / threads.y, N);

    hipLaunchKernelGGL(bmm_kernel, blocks, threads, 0, 0, 
        A.data_ptr<float>(), B.data_ptr<float>(), out.data_ptr<float>(), N, M, K, L);

    return out;
}

