11_4D_tensor_matrix_multiplication.source:
#include <torch/extension.h>
#include <hip/hip_runtime.h>
#include <ATen/hip/HIPContext.h>

__global__ void tensor_matmul_kernel(const float* A, const float* B, float* C, int b, int i, int j, int l, int k) {
    int idx_b = blockIdx.z;
    int idx_i = blockIdx.y;
    int idx_j = blockIdx.x;
    int idx_k = threadIdx.x;

    float value = 0.0f;
    for (int idx_l = 0; idx_l < l; ++idx_l) {
        value += A[idx_b * i * j * l + idx_i * j * l + idx_j * l + idx_l] * B[idx_l * k + idx_k];
    }
    C[idx_b * i * j * k + idx_i * j * k + idx_j * k + idx_k] = value;
}

torch::Tensor tensor_matmul_rocm(torch::Tensor A, torch::Tensor B) {
    auto b = A.size(0);
    auto i = A.size(1);
    auto j = A.size(2);
    auto l = A.size(3);
    auto k = B.size(1);

    auto C = torch::zeros({b, i, j, k}, A.options());

    dim3 blocks(j, i, b);
    int threads = k;

    tensor_matmul_kernel<<<blocks, threads>>>(A.data_ptr<float>(), B.data_ptr<float>(), C.data_ptr<float>(), b, i, j, l, k);

    return C;
}

