23_Softmax.source:
#include <torch/extension.h>
#include <hip/hip_runtime.h>
#include <ATen/hip/HIPContext.h>

__global__ void softmax_kernel(const float* input, float* output, int batch_size, int num_features) {
    int idx = blockIdx.x * blockDim.x + threadIdx.x;
    if (idx < batch_size) {
        float max_val = input[idx * num_features];
        for (int i = 1; i < num_features; ++i) {
            if (input[idx * num_features + i] > max_val) {
                max_val = input[idx * num_features + i];
            }
        }

        float sum = 0.0f;
        for (int i = 0; i < num_features; ++i) {
            sum += expf(input[idx * num_features + i] - max_val);
        }

        for (int i = 0; i < num_features; ++i) {
            output[idx * num_features + i] = expf(input[idx * num_features + i] - max_val) / sum;
        }
    }
}

torch::Tensor softmax_rocm(torch::Tensor input) {
    int batch_size = input.size(0);
    int num_features = input.size(1);
    auto output = torch::zeros_like(input);

    const int block_size = 256;
    const int num_blocks = (batch_size + block_size - 1) / block_size;

    softmax_kernel<<<num_blocks, block_size>>>(input.data_ptr<float>(), output.data_ptr<float>(), batch_size, num_features);

    return output;
}

