#include <torch/extension.h>
#include <hip/hip_runtime.h>
#include <ATen/hip/HIPContext.h>

__global__ void batch_norm_forward_kernel(
    const float* input, const float* weight, const float* bias,
    const float* running_mean, const float* running_var, float* output,
    int batch_size, int num_features, int spatial_size, float eps) {
    int idx = blockIdx.x * blockDim.x + threadIdx.x;
    if (idx < batch_size * num_features * spatial_size) {
        int b = idx / (num_features * spatial_size);
        int c = (idx / spatial_size) % num_features;
        float normed = (input[idx] - running_mean[c]) / sqrtf(running_var[c] + eps);
        output[idx] = normed * weight[c] + bias[c];
    }
}

torch::Tensor batch_norm_forward_rocm(
    torch::Tensor input, torch::Tensor weight, torch::Tensor bias,
    torch::Tensor running_mean, torch::Tensor running_var, float eps) {
    int batch_size = input.size(0);
    int num_features = input.size(1);
    int spatial_size = input.size(2) * input.size(3);
    auto output = torch::zeros_like(input);

    const int block_size = 256;
    const int num_blocks = (batch_size * num_features * spatial_size + block_size - 1) / block_size;

    batch_norm_forward_kernel<<<num_blocks, block_size>>>(
        input.data_ptr<float>(), weight.data_ptr<float>(), bias.data_ptr<float>(),
        running_mean.data_ptr<float>(), running_var.data_ptr<float>(), output.data_ptr<float>(),
        batch_size, num_features, spatial_size, eps);

    return output;
}

