#include <torch/extension.h>
#include <hip/hip_runtime.h>
#include <ATen/hip/HIPContext.h>

__global__ void compute_mean_var_kernel(const float* x, float* mean, float* var, int num_groups, int channels_per_group, int hw_size) {
    int b = blockIdx.x;
    int g = blockIdx.y;

    float sum = 0.0f;
    float square_sum = 0.0f;

    for (int c = 0; c < channels_per_group; ++c) {
        for (int hw = threadIdx.x; hw < hw_size; hw += blockDim.x) {
            int idx = ((b * num_groups + g) * channels_per_group + c) * hw_size + hw;
            float val = x[idx];
            sum += val;
            square_sum += val * val;
        }
    }

    __shared__ float shared_sum[256];
    __shared__ float shared_square_sum[256];

    shared_sum[threadIdx.x] = sum;
    shared_square_sum[threadIdx.x] = square_sum;
    __syncthreads();

    for (int stride = blockDim.x / 2; stride > 0; stride /= 2) {
        if (threadIdx.x < stride) {
            shared_sum[threadIdx.x] += shared_sum[threadIdx.x + stride];
            shared_square_sum[threadIdx.x] += shared_square_sum[threadIdx.x + stride];
        }
        __syncthreads();
    }

    if (threadIdx.x == 0) {
        mean[b * num_groups + g] = shared_sum[0] / (channels_per_group * hw_size);
        var[b * num_groups + g] = (shared_square_sum[0] / (channels_per_group * hw_size)) - (mean[b * num_groups + g] * mean[b * num_groups + g]);
    }
}

__global__ void normalize_kernel(const float* x, const float* mean, const float* var, float* out, const float* gamma, const float* beta, int num_groups, int channels_per_group, int hw_size, float eps) {
    int b = blockIdx.x;
    int g = blockIdx.y;
    int c = blockIdx.z * blockDim.x + threadIdx.x;

    if (c < channels_per_group) {
        for (int hw = 0; hw < hw_size; ++hw) {
            int idx = ((b * num_groups + g) * channels_per_group + c) * hw_size + hw;
            float m = mean[b * num_groups + g];
            float v = var[b * num_groups + g];
            float norm_val = (x[idx] - m) / sqrtf(v + eps);
            out[idx] = gamma[g * channels_per_group + c] * norm_val + beta[g * channels_per_group + c];
        }
    }
}

torch::Tensor group_norm_rocm(torch::Tensor x, torch::Tensor gamma, torch::Tensor beta, int num_features, int num_groups, float eps=1e-5) {
    int batch_size = x.size(0);
    int channels_per_group = num_features / num_groups;
    int hw_size = x.size(2) * x.size(3);

    auto mean = torch::zeros({batch_size, num_groups}, x.options());
    auto var = torch::zeros({batch_size, num_groups}, x.options());

    dim3 grid_mean_var(batch_size, num_groups);
    dim3 block(256);
    compute_mean_var_kernel<<<grid_mean_var, block>>>(x.data_ptr<float>(), mean.data_ptr<float>(), var.data_ptr<float>(), num_groups, channels_per_group, hw_size);

    auto out = torch::zeros_like(x);
    dim3 grid_norm(batch_size, num_groups, (channels_per_group + 255) / 256);
    normalize_kernel<<<grid_norm, block>>>(x.data_ptr<float>(), mean.data_ptr<float>(), var.data_ptr<float>(), out.data_ptr<float>(), gamma.data_ptr<float>(), beta.data_ptr<float>(), num_groups, channels_per_group, hw_size, eps);

    return out;
}

