#include <cmath>

__global__ void frobenius_norm_kernel(const float* x, float* out, float* norm, int total_elements) {
    __shared__ float shared_mem[256];
    int tid = threadIdx.x;
    int idx = blockIdx.x * blockDim.x + threadIdx.x;
    float sum = 0.0f;

    if (idx < total_elements) {
        float val = x[idx];
        sum = val * val;
    }

    shared_mem[tid] = sum;
    __syncthreads();

    for (int s = blockDim.x / 2; s > 0; s >>= 1) {
        if (tid < s) {
            shared_mem[tid] += shared_mem[tid + s];
        }
        __syncthreads();
    }

    if (tid == 0) {
        atomicAdd(norm, shared_mem[0]);
    }
}

__global__ void normalize_kernel(const float* x, float* out, float norm, int total_elements) {
    int idx = blockIdx.x * blockDim.x + threadIdx.x;
    if (idx < total_elements) {
        out[idx] = x[idx] / norm;
    }
}

torch::Tensor frobenius_norm_rocm(torch::Tensor x) {
    auto total_elements = x.numel();
    auto out = torch::zeros_like(x);
    auto norm = torch::zeros(1, x.options());

    const int block_size = 256;
    const int num_blocks = (total_elements + block_size - 1) / block_size;

    frobenius_norm_kernel<<<num_blocks, block_size>>>(x.data_ptr<float>(), out.data_ptr<float>(), norm.data_ptr<float>(), total_elements);
    normalize_kernel<<<num_blocks, block_size>>>(x.data_ptr<float>(), out.data_ptr<float>(), sqrt(norm.item<float>()), total_elements);

    return out;
}

