__global__ void l1_norm_kernel(const float* x, float* out, int batch_size, int dim) {
    int i = blockIdx.x * blockDim.x + threadIdx.x;
    if (i < batch_size) {
        float sum = 0.0f;
        for (int j = 0; j < dim; j++) {
            sum += fabsf(x[i * dim + j]);
        }
        for (int j = 0; j < dim; j++) {
            out[i * dim + j] = x[i * dim + j] / sum;
        }
    }
}

