__global__ void l2_norm_kernel(const float* x, float* out, int num_elements, int dim) {
    int idx = blockIdx.x * blockDim.x + threadIdx.x;
    if (idx < num_elements) {
        int batch_idx = idx / dim;
        int element_idx = idx % dim;
        float sum = 0.0f;
        for (int i = 0; i < dim; ++i) {
            sum += x[batch_idx * dim + i] * x[batch_idx * dim + i];
        }
        out[idx] = x[idx] / sqrt(sum);
    }
}

