#include <torch/extension.h>
#include <hip/hip_runtime.h>
#include <ATen/hip/HIPContext.h>

__global__ void bmm_kernel(const float* A, const float* B, float* C, int batch_size, int m, int k, int n) {
    int batch = blockIdx.z;
    int row = blockIdx.y * blockDim.y + threadIdx.y;
    int col = blockIdx.x * blockDim.x + threadIdx.x;

    if (row < m && col < n) {
        float sum = 0.0f;
        for (int i = 0; i < k; ++i) {
            sum += A[batch * m * k + row * k + i] * B[batch * k * n + i * n + col];
        }
        C[batch * m * n + row * n + col] = sum;
    }
}

torch::Tensor bmm_rocm(torch::Tensor A, torch::Tensor B) {
    auto sizes = A.sizes();
    int batch_size = sizes[0];
    int m = sizes[1];
    int k = sizes[2];
    int n = B.size(2);

    auto C = torch::zeros({batch_size, m, n}, A.options());

    dim3 threads(16, 16);
    dim3 blocks((n + threads.x - 1) / threads.x, (m + threads.y - 1) / threads.y, batch_size);

    bmm_kernel<<<blocks, threads>>>(A.data_ptr<float>(), B.data_ptr<float>(), C.data_ptr<float>(), batch_size, m, k, n);

    return C;
}

