#include <torch/extension.h>
#include <hip/hip_runtime.h>
#include <ATen/hip/HIPContext.h>

__global__ void layer_norm_kernel(const float* x, const float* gamma, const float* beta, float* out, int outer_size, int inner_size, float epsilon) {
    int outer_idx = blockIdx.x * blockDim.x + threadIdx.x;
    if (outer_idx < outer_size) {
        float sum = 0.0f;
        float sum_sq = 0.0f;

        for (int inner_idx = 0; inner_idx < inner_size; ++inner_idx) {
            float val = x[outer_idx * inner_size + inner_idx];
            sum += val;
            sum_sq += val * val;
        }

        float mean = sum / inner_size;
        float var = (sum_sq / inner_size) - (mean * mean);
        float inv_std = rsqrtf(var + epsilon);

        for (int inner_idx = 0; inner_idx < inner_size; ++inner_idx) {
            out[outer_idx * inner_size + inner_idx] = gamma[inner_idx] * (x[outer_idx * inner_size + inner_idx] - mean) * inv_std + beta[inner_idx];
        }
    }
}

torch::Tensor layer_norm_rocm(torch::Tensor x, torch::Tensor gamma, torch::Tensor beta, float epsilon) {
    int outer_size = x.numel() / gamma.numel();
    auto out = torch::empty_like(x);

    const int block_size = 256;
    const int num_blocks = (outer_size + block_size - 1) / block_size;

    hipLaunchKernelGGL(layer_norm_kernel, num_blocks, block_size, 0, 0, x.data_ptr<float>(), gamma.data_ptr<float>(), beta.data_ptr<float>(), out.data_ptr<float>(), outer_size, gamma.numel(), epsilon);

    return out;
}

