#include <torch/extension.h>
#include <hip/hip_runtime.h>
#include <cfloat>

__global__ void maxpool2d_kernel(const float* input, float* output, int batch_size, int channels, int height, int width, int pooled_height, int pooled_width, int kernel_size, int stride, int padding, int dilation) {
    int ph = blockIdx.x * blockDim.x + threadIdx.x;
    int pw = blockIdx.y * blockDim.y + threadIdx.y;
    int c = blockIdx.z % channels;
    int n = blockIdx.z / channels;
    if (ph < pooled_height && pw < pooled_width) {
        float max_val = -FLT_MAX;
        for (int kh = 0; kh < kernel_size; ++kh) {
            for (int kw = 0; kw < kernel_size; ++kw) {
                int h = ph * stride - padding + kh * dilation;
                int w = pw * stride - padding + kw * dilation;
                if (h >= 0 && h < height && w >= 0 && w < width) {
                    int idx = ((n * channels + c) * height + h) * width + w;
                    float val = input[idx];
                    if (val > max_val) {
                        max_val = val;
                    }
                }
            }
        }
        int out_idx = ((n * channels + c) * pooled_height + ph) * pooled_width + pw;
        output[out_idx] = max_val;
    }
}

torch::Tensor maxpool2d_rocm(torch::Tensor input, int kernel_size, int stride, int padding, int dilation) {
    int batch_size = input.size(0);
    int channels = input.size(1);
    int height = input.size(2);
    int width = input.size(3);
    int pooled_height = (height + 2 * padding - dilation * (kernel_size - 1) - 1) / stride + 1;
    int pooled_width = (width + 2 * padding - dilation * (kernel_size - 1) - 1) / stride + 1;
    auto output = torch::zeros({batch_size, channels, pooled_height, pooled_width}, input.options());
    dim3 block(16, 16);
    dim3 grid((pooled_height + block.x - 1) / block.x, (pooled_width + block.y - 1) / block.y, batch_size * channels);
    hipLaunchKernelGGL(maxpool2d_kernel, grid, block, 0, 0, input.data_ptr<float>(), output.data_ptr<float>(), batch_size, channels, height, width, pooled_height, pooled_width, kernel_size, stride, padding, dilation);
    return output;
}

