#include <torch/extension.h>
#include <hip/hip_runtime.h>
#include <ATen/hip/HIPContext.h>

__global__ void avg_pool1d_kernel(const float* input, float* output, int batch_size, int in_channels, int input_length, int output_length, int kernel_size, int stride, int padding) {
    int idx = blockIdx.x * blockDim.x + threadIdx.x;
    int channel = blockIdx.y;
    int batch = blockIdx.z;
    if (idx < output_length && channel < in_channels && batch < batch_size) {
        float sum = 0.0f;
        int start = idx * stride - padding;
        int end = start + kernel_size;
        start = max(start, 0);
        end = min(end, input_length);
        int count = end - start;
        for (int i = start; i < end; ++i) {
            sum += input[batch * in_channels * input_length + channel * input_length + i];
        }
        output[batch * in_channels * output_length + channel * output_length + idx] = sum / (float)kernel_size;
    }
}

torch::Tensor avg_pool1d_rocm(torch::Tensor input, int kernel_size, int stride, int padding) {
    int batch_size = input.size(0);
    int in_channels = input.size(1);
    int input_length = input.size(2);
    int output_length = (input_length + 2 * padding - kernel_size) / stride + 1;
    auto output = torch::zeros({batch_size, in_channels, output_length}, input.options());

    dim3 block_size(256);
    dim3 grid_size((output_length + block_size.x - 1) / block_size.x, in_channels, batch_size);

    hipStream_t stream = at::hip::getCurrentHIPStreamMasqueradingAsCUDA();
    avg_pool1d_kernel<<<grid_size, block_size, 0, stream>>>(
        input.data_ptr<float>(),
        output.data_ptr<float>(),
        batch_size,
        in_channels,
        input_length,
        output_length,
        kernel_size,
        stride,
        padding
    );

    return output;
}

