#include <torch/extension.h>
#include <hip/hip_runtime.h>
#include <ATen/hip/HIPContext.h>

__global__ void avg_pool2d_kernel(const float* input, float* output, int batch_size, int channels, int height, int width, int kernel_size, int stride, int padding) {
    int output_height = (height + 2 * padding - kernel_size) / stride + 1;
    int output_width = (width + 2 * padding - kernel_size) / stride + 1;
    int output_size = output_height * output_width;

    int idx = blockIdx.x * blockDim.x + threadIdx.x;
    if (idx < batch_size * channels * output_size) {
        int b = idx / (channels * output_size);
        int c = (idx % (channels * output_size)) / output_size;
        int oh = (idx % output_size) / output_width;
        int ow = idx % output_width;

        float sum = 0.0f;
        int count = 0;

        for (int kh = 0; kh < kernel_size; ++kh) {
            for (int kw = 0; kw < kernel_size; ++kw) {
                int ih = oh * stride + kh - padding;
                int iw = ow * stride + kw - padding;

                if (ih >= 0 && ih < height && iw >= 0 && iw < width) {
                    sum += input[b * channels * height * width + c * height * width + ih * width + iw];
                    count++;
                }
            }
        }

        output[b * channels * output_size + c * output_size + oh * output_width + ow] = sum / count;
    }
}

torch::Tensor avg_pool2d_rocm(torch::Tensor input, int kernel_size, int stride, int padding) {
    auto batch_size = input.size(0);
    auto channels = input.size(1);
    auto height = input.size(2);
    auto width = input.size(3);
    int output_height = (height + 2 * padding - kernel_size) / stride + 1;
    int output_width = (width + 2 * padding - kernel_size) / stride + 1;
    auto output = torch::zeros({batch_size, channels, output_height, output_width}, torch::kFloat32).to(input.device());

    int size = batch_size * channels * output_height * output_width;
    const int block_size = 256;
    const int num_blocks = (size + block_size - 1) / block_size;

    avg_pool2d_kernel<<<num_blocks, block_size>>>(input.data_ptr<float>(), output.data_ptr<float>(), batch_size, channels, height, width, kernel_size, stride, padding);

    return output;
}

