#include <torch/extension.h>
#include <hip/hip_runtime.h>
#include <ATen/hip/HIPContext.h>

__global__ void avg_pool3d_kernel(const float* input, float* output,
                                  int B, int C, int Din, int Hin, int Win,
                                  int kernel_d, int kernel_h, int kernel_w,
                                  int stride_d, int stride_h, int stride_w,
                                  int pad_d, int pad_h, int pad_w,
                                  int Dout, int Hout, int Wout,
                                  float inv_kernel_volume) {
    const int index = blockIdx.x * blockDim.x + threadIdx.x;
    const int total_elements = B * C * Dout * Hout * Wout;

    if (index >= total_elements) return;

    int residual = index;
    const int w_out = residual % Wout; residual /= Wout;
    const int h_out = residual % Hout; residual /= Hout;
    const int d_out = residual % Dout; residual /= Dout;
    const int c = residual % C; residual /= C;
    const int b = residual;

    const int d_start = d_out * stride_d - pad_d;
    const int h_start = h_out * stride_h - pad_h;
    const int w_start = w_out * stride_w - pad_w;

    float sum = 0.0f;

    for (int kd = 0; kd < kernel_d; ++kd) {
        int d_in = d_start + kd;
        if (d_in < 0 || d_in >= Din) continue;

        for (int kh = 0; kh < kernel_h; ++kh) {
            int h_in = h_start + kh;
            if (h_in < 0 || h_in >= Hin) continue;

            for (int kw = 0; kw < kernel_w; ++kw) {
                int w_in = w_start + kw;
                if (w_in < 0 || w_in >= Win) continue;

                int inp_idx = ((b * C + c) * Din + d_in) * Hin * Win + h_in * Win + w_in;
                sum += input[inp_idx];
            }
        }
    }

    output[index] = sum * inv_kernel_volume;
}

torch::Tensor avg_pool3d_rocm(torch::Tensor input,
                              int kernel_size,
                              int stride,
                              int padding) {
    const int kernel_d = kernel_size;
    const int kernel_h = kernel_size;
    const int kernel_w = kernel_size;
    const int stride_d = stride;
    const int stride_h = stride;
    const int stride_w = stride;
    const int pad_d = padding;
    const int pad_h = padding;
    const int pad_w = padding;

    const int B = input.size(0);
    const int C = input.size(1);
    const int Din = input.size(2);
    const int Hin = input.size(3);
    const int Win = input.size(4);

    const int Dout = (Din + 2 * pad_d - kernel_d) / stride_d + 1;
    const int Hout = (Hin + 2 * pad_h - kernel_h) / stride_h + 1;
    const int Wout = (Win + 2 * pad_w - kernel_w) / stride_w + 1;

    auto output = torch::zeros({B, C, Dout, Hout, Wout}, input.options());

    const int total = B * C * Dout * Hout * Wout;
    const int block = 256;
    const int grid = (total + block - 1) / block;

    float inv_vol = 1.0f / (kernel_d * kernel_h * kernel_w);

    hipLaunchKernelGGL(avg_pool3d_kernel,
        grid, block, 0, 0,
        input.contiguous().data_ptr<float>(),
        output.data_ptr<float>(),
        B, C, Din, Hin, Win,
        kernel_d, kernel_h, kernel_w,
        stride_d, stride_h, stride_w,
        pad_d, pad_h, pad_w,
        Dout, Hout, Wout,
        inv_vol
    );

    return output;
}

