#include <torch/extension.h>
#include <hip/hip_runtime.h>
#include <ATen/hip/HIPContext.h>

__global__ void sum_reduction_kernel(const float* input, float* output, int batch_size, int dim1, int dim2, int reduce_dim) {
    int idx = blockIdx.x * blockDim.x + threadIdx.x;
    if (reduce_dim == 1) {
        if (idx < batch_size * dim2) {
            int b = idx / dim2;
            int d2 = idx % dim2;
            float sum = 0.0f;
            for (int d1 = 0; d1 < dim1; ++d1) {
                sum += input[b * dim1 * dim2 + d1 * dim2 + d2];
            }
            output[b * dim2 + d2] = sum;
        }
    } else if (reduce_dim == 2) {
        if (idx < batch_size * dim1) {
            int b = idx / dim1;
            int d1 = idx % dim1;
            float sum = 0.0f;
            for (int d2 = 0; d2 < dim2; ++d2) {
                sum += input[b * dim1 * dim2 + d1 * dim2 + d2];
            }
            output[b * dim1 + d1] = sum;
        }
    }
}

torch::Tensor sum_reduction_rocm(torch::Tensor input, int reduce_dim) {
    int batch_size = input.size(0);
    int dim1 = input.size(1);
    int dim2 = input.size(2);
    auto output = reduce_dim == 1 ? torch::zeros({batch_size, 1, dim2}, input.options()) : torch::zeros({batch_size, dim1, 1}, input.options());

    const int block_size = 256;
    const int num_blocks = (batch_size * dim2 + block_size - 1) / block_size;

    sum_reduction_kernel<<<num_blocks, block_size>>>(input.data_ptr<float>(), output.data_ptr<float>(), batch_size, dim1, dim2, reduce_dim);

    return output;
}

