#include <torch/extension.h>
#include <hip/hip_runtime.h>
#include <ATen/hip/HIPContext.h>

__global__ void max_reduction_kernel(const float* x, float* out, int dim, int outer_size, int inner_size) {
    int outer_idx = blockIdx.x * blockDim.x + threadIdx.x;
    int inner_idx = blockIdx.y * blockDim.y + threadIdx.y;

    if (outer_idx < outer_size && inner_idx < inner_size) {
        float max_val = x[outer_idx * inner_size * dim + inner_idx];
        for (int i = 1; i < dim; ++i) {
            float val = x[outer_idx * inner_size * dim + inner_idx + i * inner_size];
            if (val > max_val) {
                max_val = val;
            }
        }
        out[outer_idx * inner_size + inner_idx] = max_val;
    }
}

torch::Tensor max_reduction_rocm(torch::Tensor x, int dim) {
    auto sizes = x.sizes();
    int outer_size = 1;
    for (int i = 0; i < dim; ++i) {
        outer_size *= sizes[i];
    }
    int inner_size = 1;
    for (int i = dim + 1; i < sizes.size(); ++i) {
        inner_size *= sizes[i];
    }
    int reduction_dim_size = sizes[dim];

    auto out = torch::zeros({outer_size, inner_size}, x.options());

    dim3 block_size(16, 16);
    dim3 num_blocks((outer_size + block_size.x - 1) / block_size.x, (inner_size + block_size.y - 1) / block_size.y);

    max_reduction_kernel<<<num_blocks, block_size>>>(x.data_ptr<float>(), out.data_ptr<float>(), reduction_dim_size, outer_size, inner_size);

    return out;
}

