__global__ void product_reduction_kernel(const float* x, float* out, int dim_size, int outer_size, int inner_size) {
    int outer_idx = blockIdx.x * blockDim.x + threadIdx.x;
    int inner_idx = blockIdx.y * blockDim.y + threadIdx.y;

    if (outer_idx < outer_size && inner_idx < inner_size) {
        float prod = 1.0f;
        for (int i = 0; i < dim_size; ++i) {
            prod *= x[outer_idx * dim_size * inner_size + i * inner_size + inner_idx];
        }
        out[outer_idx * inner_size + inner_idx] = prod;
    }
}

