    int dim_size = sizes[dim];
    int outer_size = 1;
    for (int i = 0; i < dim; ++i) {
        outer_size *= sizes[i];
    }
    int inner_size = 1;
    for (int i = dim + 1; i < x.dim(); ++i) {
        inner_size *= sizes[i];
    }

    auto out = torch::zeros({outer_size, inner_size}, x.options());

    dim3 block_size(16, 16);
    dim3 num_blocks((outer_size + block_size.x - 1) / block_size.x, (inner_size + block_size.y - 1) / block_size.y);

    product_reduction_kernel<<<num_blocks, block_size>>>(x.data_ptr<float>(), out.data_ptr<float>(), dim_size, outer_size, inner_size);

