#include <torch/extension.h>
#include <hip/hip_runtime.h>
#include <ATen/cuda/CUDAContext.h>
#include <cstdint>

template<int ReduceDim>
__global__ void argmin_kernel(const float* input, int64_t* output, int B, int D1, int D2) {
    int idx = blockIdx.x * blockDim.x + threadIdx.x;

    int output_total;
    if (ReduceDim == 0) output_total = D1 * D2;
    else if (ReduceDim == 1) output_total = B * D2;
    else output_total = B * D1;

    if (idx >= output_total) return;

    if (ReduceDim == 0) {
        int i = idx / D2;
        int j = idx % D2;
        float min_val = input[(0*D1 + i) * D2 + j];
        int min_idx = 0;
        for (int bt=1; bt < B; ++bt) {
            float val = input[(bt*D1 + i)*D2 + j];
            if (val < min_val) { min_val = val; min_idx = bt; }
        }
        output[idx] = min_idx;
    } else if (ReduceDim == 1) {
        int b = idx / D2;
        int j = idx % D2;
        float min_val = input[b*D1*D2 + j];
        int min_idx = 0;
        for (int it=1; it < D1; ++it) {
            float val = input[b*D1*D2 + it*D2 + j];
            if (val < min_val) { min_val = val; min_idx = it; }
        }
        output[idx] = min_idx;
    } else {
        int b = idx / D1;
        int i = idx % D1;
        float min_val = input[(b*D1 + i)*D2];
        int min_idx = 0;
        for (int jt=1; jt < D2; ++jt) {
            float val = input[(b*D1 + i)*D2 + jt];
            if (val < min_val) { min_val = val; min_idx = jt; }
        }
        output[idx] = min_idx;
    }
}

template __global__ void argmin_kernel<0>(const float*, int64_t*, int, int, int);
template __global__ void argmin_kernel<1>(const float*, int64_t*, int, int, int);
template __global__ void argmin_kernel<2>(const float*, int64_t*, int, int, int);

torch::Tensor argmin_rocm(torch::Tensor x, int dim) {
    TORCH_CHECK(x.is_cuda() && x.is_contiguous(), "x must be CUDA contiguous tensor");
    TORCH_CHECK(dim >=0 && dim <=2, "dim must be 0,1,2");

    int B = x.size(0), D1 = x.size(1), D2 = x.size(2);
    auto output = torch::empty({0}, torch::TensorOptions().dtype(torch::kLong).device(x.device()));

    if (dim == 0) output.resize_({D1, D2});
    else if (dim == 1) output.resize_({B, D2});
    else output.resize_({B, D1});

    int block_size = 256;
    int output_total = output.numel();
    int num_blocks = (output_total + block_size - 1) / block_size;

    auto stream = at::cuda::getCurrentCUDAStream().stream();

    switch(dim) {
        case 0: hipLaunchKernelGGL(argmin_kernel<0>, num_blocks, block_size, 0, stream, x.data_ptr<float>(), output.data_ptr<int64_t>(), B, D1, D2); break;
        case 1: hipLaunchKernelGGL(argmin_kernel<1>, num_blocks, block_size, 0, stream, x.data_ptr<float>(), output.data_ptr<int64_t>(), B, D1, D2); break;
        case 2: hipLaunchKernelGGL(argmin_kernel<2>, num_blocks, block_size, 0, stream, x.data_ptr<float>(), output.data_ptr<int64_t>(), B, D1, D2); break;
    }

    return output;
}

