#include <torch/extension.h>
#include <hip/hip_runtime.h>
#include <ATen/hip/HIPContext.h>

__global__ void min_reduction_kernel(const float* input, float* output, int dim_size, int stride, int size) {
    int idx = blockIdx.x * blockDim.x + threadIdx.x;
    if (idx < size) {
        int inner_idx = idx % stride;
        int outer_idx = idx / stride;
        int start = outer_idx * stride * dim_size + inner_idx;
        float min_val = input[start];
        for (int i = 1; i < dim_size; ++i) {
            float val = input[start + i * stride];
            if (val < min_val) {
                min_val = val;
            }
        }
        output[idx] = min_val;
    }
}

torch::Tensor min_reduction_rocm(torch::Tensor input, int dim) {
    auto sizes = input.sizes().vec();
    auto dim_size = sizes[dim];
    sizes.erase(sizes.begin() + dim);
    auto output = torch::empty(sizes, input.options());

    int size = input.numel() / dim_size;
    const int block_size = 256;
    const int num_blocks = (size + block_size - 1) / block_size;

    min_reduction_kernel<<<num_blocks, block_size>>>(input.data_ptr<float>(), output.data_ptr<float>(), dim_size, input.stride(dim), size);

    return output;
}

