55_conv_standard_2D__asymmetric_input__s.source:
#include <torch/extension.h>
#include <hip/hip_runtime.h>
#include <vector>

__global__ void conv2d_forward_kernel(
    const float* __restrict__ input,
    const float* __restrict__ weight,
    const float* __restrict__ bias,
    float* __restrict__ output,
    int batch_size, int in_channels,
    int out_channels, int in_h, int in_w,
    int kernel_size, int stride, int padding,
    int dilation, int groups,
    int out_h, int out_w) {

    const int output_idx = blockIdx.x * blockDim.x + threadIdx.x;
    if (output_idx >= batch_size * out_channels * out_h * out_w) return;

    // Decompose output index
    const int n = output_idx / (out_channels * out_h * out_w);
    const int c = (output_idx / (out_h * out_w)) % out_channels;
    const int h = (output_idx / out_w) % out_h;
    const int w = output_idx % out_w;

    const int group_size = out_channels / groups;
    const int g = c / group_size;
    const int in_c_start = g * (in_channels / groups);

    const int w_unrolled = w * stride - padding;
    const int h_unrolled = h * stride - padding;

    float value = 0.0f;

    for (int kc = 0; kc < in_channels / groups; ++kc) {
        for (int kh = 0; kh < kernel_size; ++kh) {
            for (int kw = 0; kw < kernel_size; ++kw) {
                const int in_h_idx = h_unrolled + kh * dilation;
                const int in_w_idx = w_unrolled + kw * dilation;

                if (in_h_idx >= 0 && in_h_idx < in_h && in_w_idx >= 0 && in_w_idx < in_w) {
                    const int input_idx = ((n * in_channels + (kc + in_c_start)) * in_h + in_h_idx) * in_w + in_w_idx;
                    const int weight_idx = ((c * (in_channels/groups) + kc) * kernel_size + kh) * kernel_size + kw;
                    value += input[input_idx] * weight[weight_idx];
                }
            }
        }
    }

    if (bias != nullptr) value += bias[c];
    output[output_idx] = value;
}

torch::Tensor conv2d_forward(
    torch::Tensor input,
    torch::Tensor weight,
    torch::Tensor bias,
    int stride, int padding, int dilation, int groups) {

    int batch_size = input.size(0);
    int in_channels = input.size(1);
    int in_h = input.size(2);
    int in_w = input.size(3);

    int out_channels = weight.size(0);
    int kernel_size = weight.size(2);

    // Calculate output dimensions
    int out_h = (in_h + 2 * padding - dilation * (kernel_size - 1) - 1) / stride + 1;
    int out_w = (in_w + 2 * padding - dilation * (kernel_size - 1) - 1) / stride + 1;

    auto output = torch::zeros({batch_size, out_channels, out_h, out_w}, input.options());
    int output_size = output.numel();

    const float* bias_ptr = bias.defined() ? bias.data_ptr<float>() : nullptr;

    int threads = 256;
    int blocks = (output_size + threads - 1) / threads;

    hipLaunchKernelGGL(conv2d_forward_kernel, blocks, threads, 0, 0,
        input.data_ptr<float>(),
        weight.data_ptr<float>(),
        bias_ptr,
        output.data_ptr<float>(),
        batch_size, in_channels, out_channels, in_h, in_w,
        kernel_size, stride, padding, dilation, groups,
        out_h, out_w
    );

    return output;
}

