#include <torch/extension.h>
#include <hip/hip_runtime.h>
#include <ATen/hip/HIPContext.h>

__global__ void conv_transpose2d_kernel(
    const float* input,
    const float* weight,
    float* output,
    int stride,
    int padding,
    int output_padding,
    int kernel_size,
    int in_channels,
    int out_channels,
    int input_h,
    int input_w,
    int output_h,
    int output_w,
    int groups,
    const float* bias,
    int batch_size
) {
    const int thread_id = blockIdx.x * blockDim.x + threadIdx.x;
    const int elements_per_sample = out_channels * output_h * output_w;
    const int sample = thread_id / elements_per_sample;
    int remainder = thread_id % elements_per_sample;

    if (sample >= batch_size) return;

    const int c_out = remainder / (output_h * output_w);
    remainder %= (output_h * output_w);
    const int h_out = remainder / output_w;
    const int w_out = remainder % output_w;

    if (c_out >= out_channels || h_out >= output_h || w_out >= output_w) return;

    const int out_channels_per_group = out_channels / groups;
    const int group = c_out / out_channels_per_group;
    const int in_channels_per_group = in_channels / groups;
    const int start_c_in = group * in_channels_per_group;

    float value = (bias != nullptr) ? bias[c_out] : 0.0f;

    for (int kh = 0; kh < kernel_size; ++kh) {
        for (int kw = 0; kw < kernel_size; ++kw) {
            const int h_in = (h_out - kh + padding) / stride;
            const int w_in_e = (w_out - kw + padding);
            const int w_in = w_in_e / stride;

            if (h_in < 0 || h_in >= input_h) continue;
            if (w_in < 0 || w_in >= input_w) continue;
            if ((h_in * stride) != (h_out - kh + padding - output_padding)) continue;
            if ((w_in * stride) != (w_in_e - output_padding)) continue;

            for (int c_in_offset = 0; c_in_offset < in_channels_per_group; ++c_in_offset) {
                const int c_in = start_c_in + c_in_offset;
                const int input_idx = ((sample * in_channels + c_in) * input_h + h_in) * input_w + w_in;
                const int weight_idx = ((c_in * out_channels_per_group + (c_out % out_channels_per_group)) * kernel_size + kh) * kernel_size + kw;
                value += input[input_idx] * weight[weight_idx];
            }
        }
    }

    const int output_idx = ((sample * out_channels + c_out) * output_h + h_out) * output_w + w_out;
    output[output_idx] = value;
}

torch::Tensor conv_transpose2d_rocm(
    torch::Tensor input,
    torch::Tensor weight,
    int stride,
    int padding,
    int output_padding,
    int groups,
    torch::Tensor bias,
    int kernel_size,
    int output_h,
    int output_w
) {
    const int batch_size = input.size(0);
    const int in_channels = input.size(1);
    const int input_h = input.size(2);
    const int input_w = input.size(3);
    const int out_channels = weight.size(1) * groups;

    auto output = torch::zeros({batch_size, out_channels, output_h, output_w}, input.options());
    const int total_elements = batch_size * out_channels * output_h * output_w;

    const int block_size = 256;
    const int grid_size = (total_elements + block_size - 1) / block_size;

    hipLaunchKernelGGL(conv_transpose2d_kernel,
        dim3(grid_size), dim3(block_size), 0, at::hip::getCurrentHIPStream(),
        input.data_ptr<float>(),
        weight.data_ptr<float>(),
        output.data_ptr<float>(),
        stride,
        padding,
        output_padding,
        kernel_size,
        in_channels,
        out_channels,
        input_h,
        input_w,
        output_h,
        output_w,
        groups,
        bias.defined() ? bias.data_ptr<float>() : nullptr,
        batch_size
    );

    return output;
}

