#include <torch/extension.h>
#include <hip/hip_runtime.h>
#include <ATen/hip/HIPContext.h>

__global__ void conv_transpose3d_kernel(
    const float* input, const float* weight, const float* bias,
    float* output,
    int batch_size, int in_channels, int out_channels,
    int D_in, int H_in, int W_in,
    int kD, int kH, int kW,
    int stride_d, int stride_h, int stride_w,
    int padding_d, int padding_h, int padding_w,
    int groups
) {
    int n = blockIdx.x * blockDim.x + threadIdx.x;
    int c_out = blockIdx.y * blockDim.y + threadIdx.y;
    int spatial_idx = blockIdx.z * blockDim.z + threadIdx.z;

    int D_out = (D_in - 1) * stride_d - 2 * padding_d + kD;
    int H_out = (H_in - 1) * stride_h - 2 * padding_h + kH;
    int W_out = (W_in - 1) * stride_w - 2 * padding_w + kW;

    int total_spatial = D_out * H_out * W_out;
    if (n >= batch_size || c_out >= out_channels || spatial_idx >= total_spatial) return;

    int d_out = spatial_idx / (H_out * W_out);
    int residual = spatial_idx % (H_out * W_out);
    int h_out = residual / W_out;
    int w_out = residual % W_out;

    float sum = 0.0f;
    int group_id = c_out / (out_channels / groups);
    int in_start = group_id * (in_channels / groups);
    int in_end = in_start + (in_channels / groups);

    for (int c_in = in_start; c_in < in_end; ++c_in) {
        for (int kd = 0; kd < kD; ++kd) {
            int d_in = (d_out - kd + padding_d) / stride_d;
            if (d_in * stride_d != d_out - kd + padding_d || d_in < 0 || d_in >= D_in) continue;

            for (int kh = 0; kh < kH; ++kh) {
                int h_in = (h_out - kh + padding_h) / stride_h;
                if (h_in * stride_h != h_out - kh + padding_h || h_in < 0 || h_in >= H_in) continue;

                for (int kw = 0; kw < kW; ++kw) {
                    int w_in = (w_out - kw + padding_w) / stride_w;
                    if (w_in * stride_w != w_out - kw + padding_w || w_in < 0 || w_in >= W_in) continue;

                    long input_idx = n * in_channels * D_in * H_in * W_in +
                                   c_in * D_in * H_in * W_in +
                                   d_in * H_in * W_in +
                                   h_in * W_in +
                                   w_in;

                    int weight_idx = c_in * (out_channels / groups) * kD * kH * kW +
                                   (c_out % (out_channels / groups)) * kD * kH * kW +
                                   kd * kH * kW + kh * kW + kw;

                    sum += input[input_idx] * weight[weight_idx];
                }
            }
        }
    }

    if (bias != nullptr) sum += bias[c_out];

    long output_idx = n * out_channels * D_out * H_out * W_out +
                    c_out * D_out * H_out * W_out +
                    d_out * H_out * W_out +
                    h_out * W_out +
                    w_out;
    output[output_idx] = sum;
}

torch::Tensor conv_transpose3d_rocm(torch::Tensor input, torch::Tensor weight, torch::Tensor bias,
                                    std::vector<int64_t> stride, std::vector<int64_t> padding, 
                                    std::vector<int64_t> output_padding, int groups) {
    auto input_dims = input.sizes();
    int batch_size = input_dims[0];
    int in_channels = input_dims[1];
    int D_in = input_dims[2], H_in = input_dims[3], W_in = input_dims[4];
    int kD = weight.size(2), kH = weight.size(3), kW = weight.size(4);
    int out_channels = weight.size(1) * groups;

    int D_out = (D_in - 1) * stride[0] - 2 * padding[0] + kD + output_padding[0];
    int H_out = (H_in - 1) * stride[1] - 2 * padding[1] + kH + output_padding[1];
    int W_out = (W_in - 1) * stride[2] - 2 * padding[2] + kW + output_padding[2];

    auto output = torch::zeros({batch_size, out_channels, D_out, H_out, W_out}, input.options());

    dim3 block(4, 4, 64);  // Optimize based on your hardware
    dim3 grid(
        (batch_size + block.x - 1) / block.x,
        (out_channels + block.y - 1) / block.y,
        (D_out * H_out * W_out + block.z - 1) / block.z
    );

    hipLaunchKernelGGL(conv_transpose3d_kernel, grid, block, 0, 0,
        input.data_ptr<float>(), weight.data_ptr<float>(), 
        bias.defined() ? bias.data_ptr<float>() : nullptr,
        output.data_ptr<float>(),
        batch_size, in_channels, out_channels,
        D_in, H_in, W_in, kD, kH, kW,
        stride[0], stride[1], stride[2],
        padding[0], padding[1], padding[2],
        groups
    );

    return output;
}

