class ModelNew(nn.Module):
    def __init__(self, in_channels: int, out_channels: int, kernel_size: tuple, stride: tuple = (1, 1, 1), padding: tuple = (0, 0, 0), output_padding: tuple = (0, 0, 0), groups: int = 1, bias: bool = False):
        super().__init__()
        self.in_channels = in_channels
        self.out_channels = out_channels
        self.kernel_size = kernel_size
        self.stride = list(stride)
        self.padding = list(padding)
        self.output_padding = list(output_padding)
        self.groups = groups

        self.weight = nn.Parameter(torch.Tensor(
            in_channels, out_channels // groups, *kernel_size
        ))
        if bias:
            self.bias = nn.Parameter(torch.Tensor(out_channels))
        else:
            self.register_parameter('bias', None)
        nn.init.kaiming_uniform_(self.weight, a=5**0.5)
        if bias:
            bound = 1 / (self.weight[0].numel() ** 0.5)
            nn.init.uniform_(self.bias, -bound, bound)
        self.custom_op = elementwise_add

    def forward(self, x: torch.Tensor) -> torch.Tensor:
        return self.custom_op.conv_transpose3d_rocm(
            x, self.weight, self.bias if self.bias is not None else torch.Tensor(),
            self.stride, self.padding, self.output_padding, self.groups
        )

