#include <torch/extension.h>
#include <hip/hip_runtime.h>
#include <vector>

__global__ void conv3d_kernel(
    const float* input, const float* weight, float* output,
    int N, int C_in, int C_out,
    int D_in, int H_in, int W_in,
    int Kd, int Kh, int Kw,
    int pad_d, int pad_h, int pad_w,
    int stride_d, int stride_h, int stride_w,
    int dilation_d, int dilation_h, int dilation_w,
    int groups,
    int D_out, int H_out, int W_out) {

    int idx = blockIdx.x * blockDim.x + threadIdx.x;
    if (idx >= N * C_out * D_out * H_out * W_out) return;

    int remaining = idx;
    const int w_out = remaining % W_out; remaining /= W_out;
    const int h_out = remaining % H_out; remaining /= H_out;
    const int d_out = remaining % D_out; remaining /= D_out;
    const int c_out = remaining % C_out; remaining /= C_out;
    const int n = remaining;

    const int group_in_channels = C_in / groups;
    const int group_idx = c_out / (C_out / groups);
    const int c_in_start = group_idx * group_in_channels;

    float sum = 0.0f;
    for (int c_in = c_in_start; c_in < c_in_start + group_in_channels; c_in++) {
        for (int kd = 0; kd < Kd; kd++) {
            const int d_in = d_out * stride_d - pad_d + kd * dilation_d;
            if (d_in < 0 || d_in >= D_in) continue;

            for (int kh = 0; kh < Kh; kh++) {
                const int h_in = h_out * stride_h - pad_h + kh * dilation_h;
                if (h_in < 0 || h_in >= H_in) continue;

                for (int kw = 0; kw < Kw; kw++) {
                    const int w_in = w_out * stride_w - pad_w + kw * dilation_w;
                    if (w_in < 0 || w_in >= W_in) continue;

                    const int input_idx = ((n * C_in + c_in) * D_in + d_in) * H_in * W_in + h_in * W_in + w_in;
                    const int weight_idx = ((c_out * (C_in/groups) + (c_in - c_in_start)) * Kd + kd) * Kh * Kw + kh * Kw + kw;

                    sum += input[input_idx] * weight[weight_idx];
                }
            }
        }
    }
    output[idx] = sum;
}

torch::Tensor conv3d_forward(
    torch::Tensor input, torch::Tensor weight,
    int stride_d, int stride_h, int stride_w,
    int pad_d, int pad_h, int pad_w,
    int dilation_d, int dilation_h, int dilation_w,
    int groups, int C_out) {

    const auto N = input.size(0);
    const auto C_in = input.size(1);
    const auto D_in = input.size(2);
    const auto H_in = input.size(3);
    const auto W_in = input.size(4);

    const auto Kd = weight.size(2);
    const auto Kh = weight.size(3);
    const auto Kw = weight.size(4);

    const int D_out = (D_in + 2 * pad_d - dilation_d * (Kd - 1) - 1) / stride_d + 1;
    const int H_out = (H_in + 2 * pad_h - dilation_h * (Kh - 1) - 1) / stride_h + 1;
    const int W_out = (W_in + 2 * pad_w - dilation_w * (Kw - 1) - 1) / stride_w + 1;

    auto output = torch::zeros({N, C_out, D_out, H_out, W_out}, input.options());
    const int total_elements = N * C_out * D_out * H_out * W_out;

    const int block_size = 256;
    const int num_blocks = (total_elements + block_size - 1) / block_size;

    hipLaunchKernelGGL(conv3d_kernel, dim3(num_blocks), dim3(block_size), 0, 0,
        input.data_ptr<float>(), weight.data_ptr<float>(), output.data_ptr<float>(),
        N, C_in, C_out,
        D_in, H_in, W_in,
        Kd, Kh, Kw,
        pad_d, pad_h, pad_w,
        stride_d, stride_h, stride_w,
        dilation_d, dilation_h, dilation_w,
        groups,
        D_out, H_out, W_out
    );

    return output;
}

