#include <torch/extension.h>
#include <hip/hip_runtime.h>

__global__ void conv_transpose3d_kernel(
    const float* input, const float* weight, const float* bias, float* output,
    int batch_size, int in_channels, int out_channels,
    int input_depth, int input_height, int input_width,
    int output_depth, int output_height, int output_width,
    int kernel_d, int kernel_h, int kernel_w,
    int stride_d, int stride_h, int stride_w,
    int pad_d, int pad_h, int pad_w,
    int op_d, int op_h, int op_w,
    int groups, int icpg, int ocpg
) {
    int idx = blockIdx.x * blockDim.x + threadIdx.x;
    int total = batch_size * out_channels * output_depth * output_height * output_width;
    if (idx >= total) return;

    int remaining = idx;
    int batch = remaining / (out_channels * output_depth * output_height * output_width);
    remaining %= (out_channels * output_depth * output_height * output_width);
    int out_chan = remaining / (output_depth * output_height * output_width);
    remaining %= (output_depth * output_height * output_width);
    int out_d = remaining / (output_height * output_width);
    remaining %= (output_height * output_width);
    int out_h = remaining / output_width;
    int out_w = remaining % output_width;

    int group = out_chan / ocpg;
    int out_cg = out_chan % ocpg;

    float sum = (bias != nullptr) ? bias[out_chan] : 0.0f;

    for(int ic = 0; ic < icpg; ++ic) {
        for(int kd = 0; kd < kernel_d; ++kd) {
            for(int kh = 0; kh < kernel_h; ++kh) {
                for(int kw = 0; kw < kernel_w; ++kw) {
                    int in_d = (out_d - kd + pad_d) / stride_d;
                    if ((out_d - kd + pad_d) % stride_d != 0) continue;
                    int in_h = (out_h - kh + pad_h) / stride_h;
                    if ((out_h - kh + pad_h) % stride_h != 0) continue;
                    int in_w = (out_w - kw + pad_w) / stride_w;
                    if ((out_w - kw + pad_w) % stride_w != 0) continue;

                    if(in_d >= 0 && in_d < input_depth && in_h >= 0 && in_h < input_height && in_w >= 0 && in_w < input_width) {
                        int in_chan = group * icpg + ic;
                        int input_idx = (((batch * in_channels + in_chan) * input_depth + in_d) * input_height + in_h) * input_width + in_w;
                        int weight_idx = (((in_chan * ocpg + out_cg) * kernel_d + kd) * kernel_h + kh) * kernel_w + kw;

                        sum += input[input_idx] * weight[weight_idx];
                    }
                }
            }
        }
    }

    output[idx] = sum;
}

torch::Tensor conv_transpose3d_rocm(torch::Tensor input, torch::Tensor weight, c10::optional<torch::Tensor> bias,
                                   int sd, int sh, int sw, int pd, int ph, int pw, 
                                   int op_d, int op_h, int op_w, int groups, int icpg, int ocpg) {
    auto input_sizes = input.sizes();
    int batch_size = input.size(0);
    int input_depth = input.size(2);
    int input_height = input.size(3);
    int input_width = input.size(4);

    int kernel_d = weight.size(2);
    int kernel_h = weight.size(3);
    int kernel_w = weight.size(4);

    int output_depth = (input_depth-1)*sd + kernel_d - 2*pd + op_d;
    int output_height = (input_height-1)*sh + kernel_h - 2*ph + op_h;
    int output_width = (input_width-1)*sw + kernel_w - 2*pw + op_w;

    auto opts = torch::TensorOptions().dtype(input.dtype()).device(input.device());
    auto output = torch::zeros({batch_size, groups*ocpg, output_depth, output_height, output_width}, opts);
    const float* bias_ptr = bias.has_value() ? bias->data_ptr<float>() : nullptr;

    int total_elements = output.numel();
    int block_size = 256;
    int grid_size = (total_elements + block_size - 1) / block_size;

    hipLaunchKernelGGL(conv_transpose3d_kernel, grid_size, block_size, 0, 0, 
        input.data_ptr<float>(), weight.data_ptr<float>(), bias_ptr, output.data_ptr<float>(),
        batch_size, input.size(1), groups*ocpg,
        input_depth, input_height, input_width,
        output_depth, output_height, output_width,
        kernel_d, kernel_h, kernel_w,
        sd, sh, sw,
        pd, ph, pw,
        op_d, op_h, op_w,
        groups, icpg, ocpg
    );

    return output.contiguous();
}

