#include <torch/extension.h>
#include <hip/hip_runtime.h>
#include <ATen/hip/HIPContext.h>

__global__ void conv1d_fwd_kernel(
    const float* input, 
    const float* weight, 
    const float* bias,
    float* output, 
    int batch_size,
    int in_channels,
    int out_channels,
    int input_length,
    int kernel_size,
    int stride,
    int dilation,
    int output_length
) {
    int n = blockIdx.x * blockDim.x + threadIdx.x;
    int c_out = blockIdx.y * blockDim.y + threadIdx.y;
    int l_out = blockIdx.z * blockDim.z + threadIdx.z;

    if (n >= batch_size || c_out >= out_channels || l_out >= output_length) return;

    float total = 0.0f;

    for (int c_in = 0; c_in < in_channels; c_in++) {
        for (int k = 0; k < kernel_size; k++) {
            int l_in = l_out * stride + k * dilation;
            if (l_in < 0 || l_in >= input_length) continue;
            int input_idx = n * in_channels * input_length + c_in * input_length + l_in;
            int weight_idx = c_out * in_channels * kernel_size + c_in * kernel_size + k;
            total += input[input_idx] * weight[weight_idx];
        }
    }

    if (bias != nullptr) total += bias[c_out];
    int output_idx = n * out_channels * output_length + c_out * output_length + l_out;
    output[output_idx] = total;
}

torch::Tensor conv1d_rocm(torch::Tensor x, torch::Tensor weight, torch::Tensor bias, int stride, int dilation) {
    int batch_size = x.size(0);
    int in_channels = x.size(1);
    int input_length = x.size(2);
    int out_channels = weight.size(0);
    int kernel_size = weight.size(2);

    int output_length = ((input_length - dilation*(kernel_size-1) -1)/stride) +1;
    auto output = torch::zeros({batch_size, out_channels, output_length}, x.options());

    dim3 threads(8, 8, 8);
    dim3 blocks(
        (batch_size + threads.x -1)/threads.x,
        (out_channels + threads.y -1)/threads.y,
        (output_length + threads.z -1)/threads.z
    );

    hipStream_t stream = at::hip::getCurrentHIPStream().stream();
    conv1d_fwd_kernel<<<blocks, threads, 0, stream>>>(
        x.data_ptr<float>(),
        weight.data_ptr<float>(),
        bias.defined() ? bias.data_ptr<float>() : nullptr,
        output.data_ptr<float>(),
        batch_size,
        in_channels,
        out_channels,
        input_length,
        kernel_size,
        stride,
        dilation,
        output_length
    );

    return output;
}

