#include <torch/extension.h>
#include <hip/hip_runtime.h>
#include <ATen/hip/HIPContext.h>

__global__ void conv_transpose3d_kernel(
    const float* input, 
    const float* weight, 
    const float* bias, 
    float* output,
    int batch_size,
    int in_channels,
    int out_channels,
    int in_depth,
    int in_height,
    int in_width,
    int out_depth,
    int out_height,
    int out_width,
    int kernel_size,
    int stride,
    int padding,
    int dilation,
    int has_bias
) {
    int index = blockIdx.x * blockDim.x + threadIdx.x;
    int total_output_elements = batch_size * out_channels * out_depth * out_height * out_width;
    if (index >= total_output_elements) return;

    // Decompose index into 5D tensor indices
    int b = index / (out_channels * out_depth * out_height * out_width);
    int residual = index % (out_channels * out_depth * out_height * out_width);
    int oc = residual / (out_depth * out_height * out_width);
    residual %= (out_depth * out_height * out_width);
    int od = residual / (out_height * out_width);
    residual %= (out_height * out_width);
    int oh = residual / out_width;
    int ow = residual % out_width;

    float val = has_bias ? bias[oc] : 0.0f;

    for (int ic = 0; ic < in_channels; ++ic) {
        for (int kd = 0; kd < kernel_size; ++kd) {
            for (int kh = 0; kh < kernel_size; ++kh) {
                for (int kw = 0; kw < kernel_size; ++kw) {
                    int id = od + padding - kd * dilation;
                    if (id % stride != 0) continue;
                    id /= stride;
                    if (id < 0 || id >= in_depth) continue;

                    int ih = oh + padding - kh * dilation;
                    if (ih % stride != 0) continue;
                    ih /= stride;
                    if (ih < 0 || ih >= in_height) continue;

                    int iw = ow + padding - kw * dilation;
                    if (iw % stride != 0) continue;
                    iw /= stride;
                    if (iw < 0 || iw >= in_width) continue;

                    int input_idx = ((((b * in_channels + ic) * in_depth + id) * in_height + ih) * in_width + iw);
                    int weight_idx = ((((ic * out_channels + oc) * kernel_size + kd) * kernel_size + kh) * kernel_size + kw);

                    val += input[input_idx] * weight[weight_idx];
                }
            }
        }
    }
    output[index] = val;
}

torch::Tensor conv_transpose3d_rocm(
    torch::Tensor input,
    torch::Tensor weight,
    torch::Tensor bias,
    int kernel_size,
    int stride,
    int padding,
    int dilation,
    bool has_bias,
    int out_depth,
    int out_height,
    int out_width
) {
    auto batch_size = input.size(0);
    auto in_channels = input.size(1);
    auto out_channels = weight.size(1);

    auto output = torch::zeros({batch_size, out_channels, out_depth, out_height, out_width}, input.options());
    int total_elements = batch_size * out_channels * out_depth * out_height * out_width;
    int block_size = 256;
    int num_blocks = (total_elements + block_size - 1) / block_size;

    conv_transpose3d_kernel<<<num_blocks, block_size>>>(
        input.data_ptr<float>(),
        weight.data_ptr<float>(),
        has_bias ? bias.data_ptr<float>() : nullptr,
        output.data_ptr<float>(),
        batch_size,
        in_channels,
        out_channels,
        input.size(2),
        input.size(3),
        input.size(4),
        out_depth,
        out_height,
        out_width,
        kernel_size,
        stride,
        padding,
        dilation,
        has_bias
    );
    return output;
}

