#include <torch/extension.h>
#include <hip/hip_runtime.h>
#include <ATen/hip/HIPContext.h>

__global__ void conv_transpose_1d_kernel(
    const float* input,
    const float* weight,
    const float* bias,
    float* output,
    int batch_size,
    int in_channels,
    int out_channels,
    int L_in,
    int L_out,
    int kernel_size,
    int stride,
    int padding,
    int dilation
) {
    int l_out = blockIdx.x * blockDim.x + threadIdx.x;
    int oc = blockIdx.y * blockDim.y + threadIdx.y;
    int b = blockIdx.z;

    if (b >= batch_size || oc >= out_channels || l_out >= L_out) return;

    float sum = 0.0f;

    for (int ic = 0; ic < in_channels; ++ic) {
        for (int m = 0; m < kernel_size; ++m) {
            int i = (l_out + padding - m * dilation) / stride;
            int mod_check = (l_out + padding - m * dilation) % stride;

            if (mod_check != 0 || i < 0 || i >= L_in) continue;

            float input_val = input[b * (in_channels * L_in) + ic * L_in + i];
            float weight_val = weight[ic * (out_channels * kernel_size) + oc * kernel_size + m];
            sum += input_val * weight_val;
        }
    }

    if (bias != nullptr) sum += bias[oc];

    output[b * (out_channels * L_out) + oc * L_out + l_out] = sum;
}

torch::Tensor conv_transpose1d_rocm(torch::Tensor input, torch::Tensor weight, torch::Tensor bias, int stride, int padding, int dilation) {
    TORCH_CHECK(input.dim() == 3, "Input must be 3D (batch, in_channels, length_in)");
    TORCH_CHECK(weight.dim() == 3, "Weight must be 3D (in_channels, out_channels, kernel_size)");
    TORCH_CHECK(bias.dim() == 1, "Bias must be 1D");

    int batch_size = input.size(0);
    int in_channels = input.size(1);
    int L_in = input.size(2);

    int out_channels = weight.size(1);
    int kernel_size = weight.size(2);
    int L_out = (L_in - 1) * stride - 2 * padding + dilation * (kernel_size - 1) + 1;

    auto output = torch::zeros({batch_size, out_channels, L_out}, input.options());
    if (output.numel() == 0) return output;

    hipStream_t stream = at::hip::getCurrentHIPStream();
    dim3 block(256, 1);
    dim3 grid(
        (L_out + block.x - 1) / block.x,
        (out_channels + block.y - 1) / block.y,
        batch_size
    );

    conv_transpose_1d_kernel<<<grid, block, 0, stream>>>(
        input.data_ptr<float>(),
        weight.data_ptr<float>(),
        bias.defined() ? bias.data_ptr<float>() : nullptr,
        output.data_ptr<float>(),
        batch_size,
        in_channels,
        out_channels,
        L_in,
        L_out,
        kernel_size,
        stride,
        padding,
        dilation
    );

    return output;
}

