#include <torch/extension.h>
#include <hip/hip_runtime.h>
#include <ATen/hip/HIPContext.h>

__global__ void matmul_kernel(const float* A, const float* B, float* C, int M, int N, int K) {
    const int TILE_SIZE = 32;
    __shared__ float As[TILE_SIZE][TILE_SIZE];
    __shared__ float Bs[TILE_SIZE][TILE_SIZE];

    int row = blockIdx.y * TILE_SIZE + threadIdx.y;
    int col = blockIdx.x * TILE_SIZE + threadIdx.x;

    if (row < M) {
        As[threadIdx.y][threadIdx.x] = A[row * K + threadIdx.x];
    }

    if (col < N) {
        Bs[threadIdx.y][threadIdx.x] = B[threadIdx.y * N + col];
    }

    __syncthreads();

    float sum = 0.0f;
    for (int k = 0; k < TILE_SIZE; ++k) {
        sum += As[threadIdx.y][k] * Bs[k][threadIdx.x];
    }

    if (row < M && col < N) {
        C[row * N + col] = sum;
    }
}

torch::Tensor matmul_rocm(torch::Tensor A, torch::Tensor B) {
    TORCH_CHECK(A.dim() == 2 && B.dim() == 2, "Inputs must be 2D");
    TORCH_CHECK(A.size(1) == B.size(0), "Matmul dimension mismatch");

    const int M = A.size(0);
    const int K = A.size(1);
    const int N = B.size(1);

    auto C = torch::zeros({M, N}, A.options());

    const int TILE_SIZE = 32;
    dim3 block(TILE_SIZE, TILE_SIZE);
    dim3 grid((N + TILE_SIZE - 1) / TILE_SIZE, (M + TILE_SIZE - 1) / TILE_SIZE);

    float* a_ptr = A.data_ptr<float>();
    float* b_ptr = B.data_ptr<float>();
    float* c_ptr = C.data_ptr<float>();

    hipLaunchKernelGGL(matmul_kernel, grid, block, 0, 0, a_ptr, b_ptr, c_ptr, M, N, K);
    return C;
}

