#include <torch/extension.h>
#include <hip/hip_runtime.h>
#include <ATen/hip/HIPContext.h>

__global__ void depthwise_conv_kernel(
    const float* input,
    const float* weight,
    float* output,
    int batch_size,
    int in_channels,
    int H_in,
    int W_in,
    int K,
    int H_out,
    int W_out,
    int stride_h,
    int padding_h,
    int dilation_h
) {
    const int global_idx = blockIdx.x * blockDim.x + threadIdx.x;
    const int total_output = batch_size * in_channels * H_out * W_out;
    if (global_idx >= total_output) return;

    int n = global_idx / (in_channels * H_out * W_out);
    int rem = global_idx % (in_channels * H_out * W_out);
    int c = rem / (H_out * W_out);
    rem = rem % (H_out * W_out);
    int h_out = rem / W_out;
    int w_out = rem % W_out;

    const float* weight_ptr = weight + c * K;
    float sum = 0.0f;

    for (int k = 0; k < K; ++k) {
        int h_in = h_out * stride_h - padding_h + k * dilation_h;
        if (h_in >= 0 && h_in < H_in) {
            int input_idx = n * in_channels * H_in * W_in + c * H_in * W_in + h_in * W_in + w_out;
            sum += input[input_idx] * weight_ptr[k];
        }
    }

    output[global_idx] = sum;
}

torch::Tensor depthwise_conv_rocm(
    torch::Tensor input,
    torch::Tensor weight,
    int H_kernel,
    int stride_h,
    int padding_h,
    int dilation_h
) {
    auto batch_size = input.size(0);
    auto in_channels = input.size(1);
    int H_in = input.size(2);
    int W_in = input.size(3);

    int H_out = (H_in + 2 * padding_h - dilation_h * (H_kernel - 1) - 1) / stride_h + 1;
    int W_out = W_in;

    auto output = torch::zeros({batch_size, in_channels, H_out, W_out}, input.options());
    int total_output = output.numel();

    const int block_size = 256;
    int num_blocks = (total_output + block_size - 1) / block_size;

    depthwise_conv_kernel<<<num_blocks, block_size>>>(
        input.data_ptr<float>(),
        weight.data_ptr<float>(),
        output.data_ptr<float>(),
        batch_size,
        in_channels,
        H_in,
        W_in,
        H_kernel,
        H_out,
        W_out,
        stride_h,
        padding_h,
        dilation_h
    );

    return output;
}

