#include <torch/extension.h>
#include <hip/hip_runtime.h>
#include <ATen/hip/HIPContext.h>

#define CHECK_HIP_ERROR(ans) { hipAssert((ans), __FILE__, __LINE__); }
inline void hipAssert(hipError_t code, const char *file, int line) {
    if (code != hipSuccess) {
        throw std::runtime_error(std::string("HIP Error: ") + 
                                hipGetErrorString(code) + 
                                " " + file + " " + 
                                std::to_string(line));
    }
}

__global__ void depthwise_conv2d_kernel(
    const float* __restrict__ input,
    const float* __restrict__ weight,
    const float* __restrict__ bias,
    float* __restrict__ output,
    int batch_size, int in_channels, int groups, 
    int kernel_size, int stride, int padding,
    int input_height, int input_width,
    int output_height, int output_width) {

    const int idx = blockIdx.x * blockDim.x + threadIdx.x;
    if (idx >= batch_size * groups * output_height * output_width) return;

    const int b = idx / (groups * output_height * output_width);
    const int g = (idx / (output_height * output_width)) % groups;
    const int h_out = (idx / output_width) % output_height;
    const int w_out = idx % output_width;

    const int h_start = h_out * stride - padding;
    const int w_start = w_out * stride - padding;

    float sum = 0.0f;
    for (int kh = 0; kh < kernel_size; ++kh) {
        for (int kw = 0; kw < kernel_size; ++kw) {
            const int h_in = h_start + kh;
            const int w_in = w_start + kw;
            if (h_in >= 0 && h_in < input_height && w_in >= 0 && w_in < input_width) {
                const int input_idx = b * in_channels * input_height * input_width + 
                                    g * input_height * input_width + 
                                    h_in * input_width + w_in;
                const int weight_idx = g * kernel_size * kernel_size + 
                                     kh * kernel_size + kw;
                sum += input[input_idx] * weight[weight_idx];
            }
        }
    }

    if (bias) {
        sum += bias[g];
    }

    output[idx] = sum;
}

torch::Tensor depthwise_conv2d_rocm(torch::Tensor input, torch::Tensor weight, torch::Tensor bias, int stride, int padding) {
    const auto batch_size = input.size(0);
    const auto in_channels = input.size(1);
    const auto input_height = input.size(2);
    const auto input_width = input.size(3);
    const auto kernel_size = weight.size(2);
    const auto groups = in_channels;

    const auto output_height = (input_height + 2 * padding - kernel_size) / stride + 1;
    const auto output_width = (input_width + 2 * padding - kernel_size) / stride + 1;

    auto output = torch::zeros({batch_size, groups, output_height, output_width}, input.options());
    const int num_elements = output.numel();

    constexpr int block_size = 256;
    const dim3 grid((num_elements + block_size - 1) / block_size);
    const dim3 block(block_size);

    hipStream_t stream = at::hip::getCurrentHIPStream();
    depthwise_conv2d_kernel<<<grid, block, 0, stream>>>(
        input.data_ptr<float>(),
        weight.data_ptr<float>(),
        bias.defined() ? bias.data_ptr<float>() : nullptr,
        output.data_ptr<float>(),
        batch_size, in_channels, groups,
        kernel_size, stride, padding,
        input_height, input_width,
        output_height, output_width
    );

    return output.reshape({batch_size, groups, output_height, output_width});
}

