#include <torch/extension.h>
#include <hip/hip_runtime.h>

__global__ void conv1x1_kernel(
    const float* input,
    const float* weight,
    const float* bias,
    float* output,
    int batch_size,
    int in_channels,
    int out_channels,
    int height,
    int width,
    int input_stride_batch,
    int input_stride_channel,
    int input_stride_height,
    int input_stride_width,
    int weight_stride_co,
    int weight_stride_ci
) {
    int idx = blockIdx.x * blockDim.x + threadIdx.x;
    int total = batch_size * out_channels * height * width;
    if (idx >= total) return;

    int elements_per_batch = out_channels * height * width;
    int b = idx / elements_per_batch;
    int tid = idx % elements_per_batch;
    int co = tid / (height * width);
    int spatial_idx = tid % (height * width);
    int h = spatial_idx / width;
    int w = spatial_idx % width;

    float sum = 0.0f;
    for (int ci = 0; ci < in_channels; ++ci) {
        int input_offset = b * input_stride_batch
                         + ci * input_stride_channel
                         + h * input_stride_height
                         + w * input_stride_width;
        int weight_offset = co * weight_stride_co
                          + ci * weight_stride_ci;
        sum += input[input_offset] * weight[weight_offset];
    }

    if (bias != nullptr) {
        sum += bias[co];
    }

    output[idx] = sum;
}

torch::Tensor conv1x1_rocm(torch::Tensor input, torch::Tensor weight, torch::Tensor bias) {
    auto input_cont = input.contiguous();
    auto weight_cont = weight.contiguous().view({weight.size(0), weight.size(1)});
    auto bias_cont = bias.defined() ? bias.contiguous() : torch::Tensor();

    auto output = torch::zeros({input_cont.size(0), weight_cont.size(0), input_cont.size(2), input_cont.size(3)}, input_cont.options());

    const float* input_ptr = input_cont.data_ptr<float>();
    const float* weight_ptr = weight_cont.data_ptr<float>();
    const float* bias_ptr = bias_cont.defined() ? bias_cont.data_ptr<float>() : nullptr;
    float* output_ptr = output.data_ptr<float>();

    auto input_strides = input_cont.strides();
    auto weight_strides = weight_cont.strides();

    int total_elements = output.numel();
    int threads = 256;
    int blocks = (total_elements + threads - 1) / threads;

    hipLaunchKernelGGL(conv1x1_kernel,
                    dim3(blocks), dim3(threads), 0, 0,
                    input_ptr,
                    weight_ptr,
                    bias_ptr,
                    output_ptr,
                    input_cont.size(0),
                    input_cont.size(1),
                    weight_cont.size(0),
                    input_cont.size(2),
                    input_cont.size(3),
                    input_strides[0],
                    input_strides[1],
                    input_strides[2],
                    input_strides[3],
                    weight_strides[0],
                    weight_strides[1]);

    return output;
}

