#include <torch/extension.h>
#include <hip/hip_runtime.h>
#include <ATen/hip/HIPContext.h>
#include <cmath>

__global__ void gelu_kernel(const float* x, float* out, int num_elements) {
    const float sqrt_2_over_pi = 0.7978845608028654f;  // sqrt(2/pi)
    const float coef = 0.044715f;

    int idx = blockIdx.x * blockDim.x + threadIdx.x;
    if (idx < num_elements) {
        float x_val = x[idx];
        float x_cubed = x_val * x_val * x_val;
        float inner = sqrt_2_over_pi * (x_val + coef * x_cubed);
        float tanh_value = tanhf(inner);
        out[idx] = 0.5f * x_val * (1.0f + tanh_value);
    }
}

torch::Tensor gelu_rocm(torch::Tensor x) {
    auto out = torch::empty_like(x);
    int num_elements = x.numel();

    const int block_size = 256;
    int grid_size = (num_elements + block_size - 1) / block_size;

    hipLaunchKernelGGL(gelu_kernel, 
        dim3(grid_size), dim3(block_size), 0, at::hip::getCurrentHIPStream(), 
        x.data_ptr<float>(), out.data_ptr<float>(), num_elements
    );

    return out;
}

