#include <torch/extension.h>
#include <hip/hip_runtime.h>
#include <ATen/hip/HIPContext.h>

constexpr int BLOCK_SIZE = 256;
constexpr int CHUNK_SIZE = 16;

__global__ void cumsum_kernel(const float* input, float* output, int dim_size) {
    extern __shared__ float shared_mem[];
    int batch_idx = blockIdx.x;
    int tid = threadIdx.x;

    float* data_shared = shared_mem;
    float* chunk_sums = shared_mem + BLOCK_SIZE * CHUNK_SIZE;

    int global_offset = batch_idx * dim_size;

    // Load data with padding
    for(int i=0; i<CHUNK_SIZE; i++) {
        int idx = tid*CHUNK_SIZE + i;
        data_shared[idx] = (idx < dim_size) ? input[global_offset + idx] : 0.0f;
    }
    __syncthreads();

    // Local prefix sums
    float local_sum = 0;
    for(int i=0; i<CHUNK_SIZE; i++) {
        int idx = tid*CHUNK_SIZE + i;
        local_sum += data_shared[idx];
        data_shared[idx] = local_sum;
    }
    chunk_sums[tid] = local_sum;
    __syncthreads();

    // Parallel prefix sum chunk sums
    for(int stride=1; stride<BLOCK_SIZE; stride*=2) {
        float val = (tid >= stride) ? chunk_sums[tid - stride] : 0.0f;
        __syncthreads();
        chunk_sums[tid] += val;
        __syncthreads();
    }

    // Shift sums for exclusive scan
    float offset = (tid > 0) ? chunk_sums[tid-1] : 0.0f;
    __syncthreads();

    // Add offset to local elements
    for(int i=0; i<CHUNK_SIZE; i++) {
        int idx = tid*CHUNK_SIZE + i;
        if(idx < dim_size) data_shared[idx] += offset;
    }
    __syncthreads();

    // Store results
    for(int i=0; i<CHUNK_SIZE; i++) {
        int idx = tid*CHUNK_SIZE + i;
        if(idx < dim_size) output[global_offset + idx] = data_shared[idx];
    }
}

torch::Tensor cumsum_rocm(torch::Tensor input, int dim) {
    auto sizes = input.sizes();
    int dim_size = sizes[dim];
    auto output = torch::empty_like(input);

    int batch_size = sizes[0];
    size_t shared_mem = (BLOCK_SIZE * CHUNK_SIZE + BLOCK_SIZE) * sizeof(float);

    hipLaunchKernelGGL(cumsum_kernel, 
        dim3(batch_size), dim3(BLOCK_SIZE), shared_mem, 0, 
        input.data_ptr<float>(), 
        output.data_ptr<float>(), 
        dim_size
    );

    return output;
}

