#include <torch/extension.h>
#include <hip/hip_runtime.h>
#include <ATen/hip/HIPContext.h>

__global__ void cumprod_kernel(const float* input, float* output, int dim_size, int batch_size) {
    extern __shared__ float s_data[];

    int batch_idx = blockIdx.x;
    if (batch_idx >= batch_size) return;

    int tid = threadIdx.x;

    int input_start = batch_idx * dim_size;
    for (int i = tid; i < dim_size; i += blockDim.x) {
        s_data[i] = input[input_start + i];
    }

    __syncthreads();

    for (int s = 1; s < dim_size; s *= 2) {
        for (int i = tid; i < dim_size; i += blockDim.x) {
            if (i >= s) {
                s_data[i] *= s_data[i - s];
            }
        }
        __syncthreads();
    }

    int output_start = batch_idx * dim_size;
    for (int i = tid; i < dim_size; i += blockDim.x) {
        output[output_start + i] = s_data[i];
    }
}

torch::Tensor cumprod_rocm(torch::Tensor input, int dim) {
    auto sizes = input.sizes();
    TORCH_CHECK(dim == 1 && sizes.size() == 2, "CUMPROD optimized for 2D tensors along dim=1");

    int batch_size = sizes[0];
    int dim_size = sizes[1];
    auto output = torch::empty_like(input);

    const int block_size = 256;
    size_t shared_size = dim_size * sizeof(float);

    hipLaunchKernelGGL(cumprod_kernel,
        dim3(batch_size), dim3(block_size), shared_size, 0,
        input.data_ptr<float>(),
        output.data_ptr<float>(),
        dim_size,
        batch_size
    );

    return output;
}

