#include <torch/extension.h>
#include <hip/hip_runtime.h>

__global__ void masked_cumsum_kernel(const float* x, const bool* mask, float* out, int batch_size, int dim_size) {
    int batch_idx = blockIdx.x * blockDim.x + threadIdx.x;
    if (batch_idx >= batch_size) return;

    const float* x_batch = x + batch_idx * dim_size;
    const bool* mask_batch = mask + batch_idx * dim_size;
    float* out_batch = out + batch_idx * dim_size;

    float cum_sum = 0.0f;
    for (int i = 0; i < dim_size; ++i) {
        if (mask_batch[i]) {
            cum_sum += x_batch[i];
        }
        out_batch[i] = cum_sum;
    }
}

torch::Tensor masked_cumsum_rocm(torch::Tensor x, torch::Tensor mask, int dim_size) {
    TORCH_CHECK(x.dim() == 2, "Expected 2D tensor (batch_size, dim_size)");
    TORCH_CHECK(x.scalar_type() == torch::kFloat32, "x must be float32");
    TORCH_CHECK(mask.scalar_type() == torch::kBool, "mask must be bool");
    TORCH_CHECK(x.sizes() == mask.sizes(), "x and mask must be same size");

    auto x_cont = x.contiguous();
    auto mask_cont = mask.contiguous();
    auto out = torch::zeros_like(x_cont);

    int batch_size = x_cont.size(0);
    const int threads = 256;
    int blocks = (batch_size + threads - 1) / threads;

    hipLaunchKernelGGL(masked_cumsum_kernel, dim3(blocks), dim3(threads), 0, 0, 
        x_cont.data_ptr<float>(), 
        mask_cont.data_ptr<bool>(), 
        out.data_ptr<float>(), 
        batch_size,
        dim_size
    );

    return out;
}

