#include <torch/extension.h>
#include <hip/hip_runtime.h>
#include <ATen/hip/HIPContext.h>

template <typename scalar_t>
__device__ scalar_t blockReduceSum(scalar_t val, scalar_t* shared) {
    int tid = threadIdx.x;
    shared[tid] = val;
    __syncthreads();

    for (int s = blockDim.x/2; s > 0; s >>= 1) {
        if (tid < s)
            shared[tid] += shared[tid + s];
        __syncthreads();
    }
    return shared[0];
}

template <typename scalar_t>
__global__ void smooth_l1_loss_kernel(const scalar_t* predictions,
                                    const scalar_t* targets,
                                    scalar_t* output,
                                    scalar_t beta,
                                    int count) {
    extern __shared__ __align__(sizeof(scalar_t)) unsigned char shared_mem[];
    scalar_t* shared = reinterpret_cast<scalar_t*>(shared_mem);

    scalar_t sum = 0.0;
    int idx = blockIdx.x * blockDim.x + threadIdx.x;

    if (idx < count) {
        scalar_t diff = predictions[idx] - targets[idx];
        scalar_t abs_diff = abs(diff);
        if (abs_diff < beta)
            sum = 0.5 * diff * diff / beta;
        else
            sum = abs_diff - 0.5 * beta;
    }

    scalar_t block_sum = blockReduceSum(sum, shared);

    if (threadIdx.x == 0)
        atomicAdd(output, block_sum); 
}

torch::Tensor smooth_l1_loss_rocm(torch::Tensor predictions, torch::Tensor targets, float beta) {
    auto count = predictions.numel();
    auto output = torch::zeros({}, predictions.options());

    const int block_size = 256;
    int grid_size = (count + block_size - 1) / block_size;

    AT_DISPATCH_FLOATING_TYPES(predictions.scalar_type(), "smooth_l1_loss", [&]{
        smooth_l1_loss_kernel<scalar_t><<<grid_size, block_size, block_size * sizeof(scalar_t)>>>(
            predictions.data_ptr<scalar_t>(),
            targets.data_ptr<scalar_t>(),
            output.data_ptr<scalar_t>(),
            static_cast<scalar_t>(beta),
            count
        );
    });

    return output.div_(count);
}

