#include <torch/extension.h>
#include <hip/hip_runtime.h>
#include <ATen/hip/HIPContext.h>
#include <cmath>

__global__ void kl_div_kernel(const float* a, const float* b, float* out, int num_elements, int batch_size) {
    extern __shared__ float sdata[];

    unsigned int tid = threadIdx.x;
    unsigned int grid_size = gridDim.x * blockDim.x;

    float thread_sum = 0.0f;

    for (unsigned int i = blockIdx.x * blockDim.x + threadIdx.x;
         i < num_elements;
         i += grid_size) {
        float a_val = a[i];
        float b_val = b[i];
        float log_a = logf(a_val);
        float log_b = logf(b_val);
        thread_sum += b_val * (log_b - log_a);
    }

    sdata[tid] = thread_sum;
    __syncthreads();

    for (unsigned int s = blockDim.x/2; s>0; s>>=1) {
        if (tid < s) {
            sdata[tid] += sdata[tid + s];
        }
        __syncthreads();
    }

    if (tid == 0) {
        atomicAdd(out, sdata[0] / batch_size);
    }
}

torch::Tensor kl_div_rocm(torch::Tensor a, torch::Tensor b) {
    TORCH_CHECK(a.sizes() == b.sizes(), "Input tensors must have same shape");
    auto batch_size = a.size(0);
    auto num_elements = a.numel();
    auto out = torch::zeros({}, a.options());

    const int block_size = 256;
    int grid_size = (num_elements + block_size - 1) / block_size;
    grid_size = std::min(grid_size, 4096);

    size_t shared_mem_size = block_size * sizeof(float);
    hipLaunchKernelGGL(kl_div_kernel, 
        dim3(grid_size), dim3(block_size), shared_mem_size, at::hip::getCurrentHIPStream(),
        a.data_ptr<float>(), b.data_ptr<float>(), out.data_ptr<float>(), num_elements, batch_size
    );

    return out;
}

