#include <torch/extension.h>
#include <hip/hip_runtime.h>
#include <ATen/hip/HIPContext.h>

__global__ void triplet_loss_kernel(
    const float* anchor, const float* positive, const float* negative,
    float margin, int batch_size, int embedding_size, float* total_loss
) {
    int batch_idx = blockIdx.x;
    if (batch_idx >= batch_size) return;

    const float* a = anchor + batch_idx * embedding_size;
    const float* p = positive + batch_idx * embedding_size;
    const float* n = negative + batch_idx * embedding_size;

    extern __shared__ float sdata[];

    float ap_acc = 0.0f;
    float an_acc = 0.0f;

    for(int i = threadIdx.x; i < embedding_size; i += blockDim.x) {
        float diff_ap = a[i] - p[i];
        ap_acc += diff_ap * diff_ap;
        float diff_an = a[i] - n[i];
        an_acc += diff_an * diff_an;
    }

    sdata[threadIdx.x] = ap_acc;
    sdata[blockDim.x + threadIdx.x] = an_acc;
    __syncthreads();

    // Reduction for AP distance
    for(int stride = blockDim.x/2; stride > 0; stride >>= 1) {
        if(threadIdx.x < stride) {
            sdata[threadIdx.x] += sdata[threadIdx.x + stride];
            sdata[blockDim.x + threadIdx.x] += sdata[blockDim.x + threadIdx.x + stride];
        }
        __syncthreads();
    }

    if(threadIdx.x == 0) {
        float ap_dist = sqrt(sdata[0]);
        float an_dist = sqrt(sdata[blockDim.x]);
        float sample_loss = fmaxf(ap_dist - an_dist + margin, 0.0f);
        atomicAdd(total_loss, sample_loss/batch_size);
    }
}

torch::Tensor triplet_loss_rocm(torch::Tensor anchor, torch::Tensor positive, torch::Tensor negative, float margin) {
    AT_ASSERTM(anchor.is_cuda(), "Anchor tensor must be on GPU");
    int batch_size = anchor.size(0);
    int embedding_size = anchor.size(1);
    const int threads = 256;

    auto options = torch::TensorOptions().dtype(torch::kFloat32).device(anchor.device());
    auto total_loss = torch::zeros(1, options);

    hipLaunchKernelGGL(triplet_loss_kernel, 
        dim3(batch_size), dim3(threads), 2*threads*sizeof(float), 0,
        anchor.contiguous().data_ptr<float>(),
        positive.contiguous().data_ptr<float>(),
        negative.contiguous().data_ptr<float>(),
        margin,
        batch_size,
        embedding_size,
        total_loss.data_ptr<float>()
    );

    return total_loss.squeeze();
}

