#include <ATen/hip/HIPContext.h>

__global__ void clamp_div_kernel(const float* input, float* output, float min_value, float divisor, int num_elements) {
    int idx = blockIdx.x * blockDim.x + threadIdx.x;
    if (idx < num_elements) {
        float val = input[idx];
        val = fmaxf(val, min_value);
        output[idx] = val / divisor;
    }
}

torch::Tensor clamp_div_rocm(torch::Tensor input, float min_value, float divisor) {
    auto output = torch::zeros_like(input);
    int num_elements = input.numel();
    const int block_size = 256;
    int grid_size = (num_elements + block_size - 1) / block_size;

    hipLaunchKernelGGL(clamp_div_kernel, 
        dim3(grid_size), 
        dim3(block_size), 
        0, 
        at::hip::getCurrentHIPStream(), 
        input.data_ptr<float>(), 
        output.data_ptr<float>(), 
        min_value, 
        divisor, 
        num_elements);

    return output;
}

10_ConvTranspose2d_MaxPool_Hardtanh_Mean.source:
#include <torch/extension.h>
#include <hip/hip_runtime.h>
#include <ATen/hip/HIPContext.h>

__global__ void maxpool_hardtanh_kernel(const float* input, float* output, int B, int C, int H, int W, int kH, int kW, int sH, int sW, float min_val, float max_val, int oH, int oW) {
    int b = blockIdx.z;
    int c = blockIdx.y;
    int h_out = blockIdx.x;
    int w_out = threadIdx.x;

    if (b >= B || c >= C || h_out >= oH || w_out >= oW) return;

    int start_h = h_out * sH;
    int start_w = w_out * sW;
    int end_h = min(start_h + kH, H);
    int end_w = min(start_w + kW, W);

    float max_val_region = -__FLT_MAX__;
    for (int h = start_h; h < end_h; ++h) {
        for (int w = start_w; w < end_w; ++w) {
            float val = input[b*C*H*W + c*H*W + h*W + w];
            if (val > max_val_region) max_val_region = val;
        }
    }

    max_val_region = fminf(max_val, fmaxf(min_val, max_val_region));
    output[b*C*oH*oW + c*oH*oW + h_out*oW + w_out] = max_val_region;
}

torch::Tensor maxpool_hardtanh_rocm(torch::Tensor x, int k, int s, float min_val, float max_val) {
    int B = x.size(0), C = x.size(1), H = x.size(2), W = x.size(3);
    int oH = (H - k)/s + 1;
    int oW = (W - k)/s + 1;
    auto output = torch::zeros({B, C, oH, oW}, x.options());

    dim3 blocks(oH, C, B);
    hipLaunchKernelGGL(maxpool_hardtanh_kernel, blocks, oW, 0, at::cuda::getCurrentHIPStream(), 
        x.data_ptr<float>(), output.data_ptr<float>(), B, C, H, W, k, k, s, s, min_val, max_val, oH, oW);

    return output;
}

11_ConvTranspose2d_BatchNorm_Tanh_MaxPoo.source:
#include <torch/extension.h>
#include <hip/hip_runtime.h>

#define CHECK_HIP(x) TORCH_CHECK(x.is_cuda(), #x " must be a HIP tensor")
#define CHECK_CONTIGUOUS(x) TORCH_CHECK(x.is_contiguous(), #x " must be contiguous")

__global__ void bn_tanh_kernel(
    const float* input, float* output, 
    const float* gamma, const float* beta,
    const float* mean, const float* var,
    int C, int H, int W, int numel, float eps) {

    int idx = blockIdx.x * blockDim.x + threadIdx.x;
    if (idx >= numel) return;

    int n = idx / (C * H * W);
    int c = (idx / (H * W)) % C;

    float inv_std = rsqrtf(var[c] + eps);
    float val = (input[idx] - mean[c]) * gamma[c] * inv_std + beta[c];
    output[idx] = tanhf(val);
}

torch::Tensor bn_tanh_rocm(
    torch::Tensor input, 
    torch::Tensor gamma,
    torch::Tensor beta,
    torch::Tensor mean,
    torch::Tensor var,
    float eps) {

    CHECK_HIP(input); CHECK_CONTIGUOUS(input);
    CHECK_HIP(gamma); CHECK_CONTIGUOUS(gamma);
    CHECK_HIP(beta); CHECK_CONTIGUOUS(beta);
    CHECK_HIP(mean); CHECK_CONTIGUOUS(mean);
    CHECK_HIP(var); CHECK_CONTIGUOUS(var);

    auto output = torch::empty_like(input);
    int numel = input.numel();
    int C = input.size(1);
    int H = input.size(2);
    int W = input.size(3);

    dim3 block(256);
    dim3 grid((numel + block.x - 1) / block.x);

    hipLaunchKernelGGL(bn_tanh_kernel, grid, block, 0, 0, 
        input.data_ptr<float>(), output.data_ptr<float>(),
        gamma.data_ptr<float>(), beta.data_ptr<float>(),
        mean.data_ptr<float>(), var.data_ptr<float>(),
        C, H, W, numel, eps);

    return output;
}

