__global__ void fused_multiply_lrelu_kernel(const float* input, float* output, float multiplier, float negative_slope, int size) {
    int idx = blockIdx.x * blockDim.x + threadIdx.x;
    if (idx < size) {
        float val = input[idx] * multiplier;
        output[idx] = (val > 0) ? val : val * negative_slope;
    }
}

