}

13_ConvTranspose3d_Mean_Add_Softmax_Tanh.source:
#include <torch/extension.h>
#include <hip/hip_runtime.h>
#include <cmath>

__global__ void fused_ops_kernel(
    const float* conv_output, 
    float* output, 
    float bias,
    float scaling_factor,
    int batch_size,
    int channels,
    int depth,
    int height,
    int width
) {
    int index = blockIdx.x * blockDim.x + threadIdx.x;
    int spatial_size = depth * height * width;
    int total_elements = batch_size * spatial_size;
    if (index >= total_elements) return;

    int batch = index / spatial_size;
    int spatial_idx = index % spatial_size;
    int d = spatial_idx / (height * width);
    int h = (spatial_idx % (height * width)) / width;
    int w = spatial_idx % width;

    float sum = 0.0f;
    for (int c = 0; c < channels; ++c) {
        int input_idx = ((batch * channels + c) * depth + d) * height * width + h * width + w;
        sum += conv_output[input_idx];
    }
    float val = sum / channels + bias;

    output[index] = tanhf(1.0f) * scaling_factor;
}

torch::Tensor fused_ops_rocm(torch::Tensor conv_output, torch::Tensor bias, float scaling_factor, int channels) {
    auto options = torch::TensorOptions().dtype(conv_output.dtype()).device(conv_output.device());
    int batch_size = conv_output.size(0);
    int depth = conv_output.size(2);
    int height = conv_output.size(3);
    int width = conv_output.size(4);
    int total_elements = batch_size * depth * height * width;
    auto output = torch::empty({batch_size, 1, depth, height, width}, options);

    const int block_size = 256;
    int grid_size = (total_elements + block_size - 1) / block_size;

    hipLaunchKernelGGL(
        fused_ops_kernel, 
        grid_size, block_size, 0, 0,
        conv_output.data_ptr<float>(),
        output.data_ptr<float>(),
        bias.item<float>(),
        scaling_factor,
        batch_size,
        channels,
        depth,
        height,
        width
    );
    return output;
}

