15_ConvTranspose3d_BatchNorm_Subtract.source:
#include <torch/extension.h>
#include <hip/hip_runtime.h>
#include <ATen/hip/HIPContext.h>

__global__ void mean_subtract_kernel(const float* input, float* output, int B, int C, int D, int H, int W) {
    extern __shared__ float shared_sum[];
    int bc = blockIdx.x;
    int b = bc / C;
    int c = bc % C;

    int spatial_size = D * H * W;
    int tid = threadIdx.x;

    float sum = 0.0f;

    for (int i = tid; i < spatial_size; i += blockDim.x) {
        int d = i / (H * W);
        int h = (i % (H * W)) / W;
        int w = i % W;
        int idx = ((b * C + c) * D + d) * H * W + h * W + w;
        sum += input[idx];
    }

    shared_sum[tid] = sum;
    __syncthreads();

    for (int s = blockDim.x / 2; s > 0; s >>= 1) {
        if (tid < s) {
            shared_sum[tid] += shared_sum[tid + s];
        }
        __syncthreads();
    }

    if (tid == 0) {
        float mean = shared_sum[0] / (float) spatial_size;
        shared_sum[0] = mean;
    }
    __syncthreads();

    float mean_val = shared_sum[0];

    for (int i = tid; i < spatial_size; i += blockDim.x) {
        int d = i / (H * W);
        int h = (i % (H * W)) / W;
        int w = i % W;
        int idx = ((b * C + c) * D + d) * H * W + h * W + w;
        output[idx] = input[idx] - mean_val;
    }
}

torch::Tensor mean_subtract_rocm(torch::Tensor x) {
    auto B = x.sizes()[0];
    auto C = x.sizes()[1];
    auto D = x.sizes()[2];
    auto H = x.sizes()[3];
    auto W = x.sizes()[4];

    torch::Tensor x_contig = x.contiguous();
    torch::Tensor output = torch::empty_like(x_contig);

    int num_blocks = B * C;
    int block_size = 256;

    size_t shared_mem = block_size * sizeof(float);

    hipStream_t stream = at::cuda::getCurrentHIPStream();

    mean_subtract_kernel<<<num_blocks, block_size, shared_mem, stream>>>(
        x_contig.data_ptr<float>(),
        output.data_ptr<float>(),
        B,
        C,
        D,
        H,
        W
    );

    return output;
}

16_ConvTranspose2d_Mish_Add_Hardtanh_Sca.source:
#include <torch/extension.h>
#include <hip/hip_runtime.h>
#include <ATen/hip/HIPContext.h>
#include <math.h>

__global__ void fused_activation_kernel(const float* input, float* output, int num_elements, float add_value, float scale) {
    int idx = blockIdx.x * blockDim.x + threadIdx.x;
    if (idx < num_elements) {
        float x = input[idx];

        float softplus_val = log1pf(expf(x));
        float mish = x * tanhf(softplus_val);
        float after_add = mish + add_value;
        float clamped = fmaxf(-1.0f, fminf(after_add, 1.0f));
        output[idx] = clamped * scale;
    }
}

