#include <torch/extension.h>
#include <hip/hip_runtime.h>
#include <ATen/hip/HIPContext.h>

__global__ void fused_post_conv_ops_kernel(const float* x_conv, const float* bias, float* out, int num_elements, int channels, int depth, int height, int width) {
    int idx = blockIdx.x * blockDim.x + threadIdx.x;
    if (idx >= num_elements) return;

    int s = idx;
    int w = s % width;
    s /= width;
    int h = s % height;
    s /= height;
    int d = s % depth;
    s /= depth;
    int c = s % channels;
    s /= channels;

    float x_val = x_conv[idx];
    float bias_val = bias[c];

    float step1 = x_val + bias_val;
    float step2 = step1 + x_val;
    float step3 = step2 * x_val;
    float step4 = step3 + x_val;

    out[idx] = step4;
}

torch::Tensor fused_post_conv_ops_rocm(torch::Tensor x_conv, torch::Tensor bias) {
    auto out = torch::empty_like(x_conv);
    int num_elements = x_conv.numel();

    auto sizes = x_conv.sizes();
    int channels = sizes[1];
    int depth = sizes[2];
    int height = sizes[3];
    int width = sizes[4];

    const int block_size = 256;
    dim3 threads(block_size);
    dim3 blocks((num_elements + block_size - 1) / block_size);

    hipLaunchKernelGGL(fused_post_conv_ops_kernel, blocks, threads, 0, 0, 
        x_conv.data_ptr<float>(), 
        bias.data_ptr<float>(), 
        out.data_ptr<float>(), 
        num_elements, channels, depth, height, width
    );

    return out;
}

