#include <torch/extension.h>
#include <hip/hip_runtime.h>
#include <ATen/hip/HIPContext.h>

__global__ void group_norm_mean_kernel(const float* input, float* output, const float* gamma, const float* beta,
                                       int batch_size, int channels, int depth, int height, int width,
                                       int num_groups, float eps) {
    int outer_size = batch_size * num_groups;
    int group_channels = channels / num_groups;
    int inner_size = group_channels * depth * height * width;

    extern __shared__ float shared[];
    float* sum_shared = shared;
    float* sum_sq_shared = &shared[outer_size];

    int outer_idx = blockIdx.x * blockDim.x + threadIdx.x;
    if (outer_idx >= outer_size) return;

    int batch = outer_idx / num_groups;
    int group = outer_idx % num_groups;

    const float* group_input = input + (batch * channels + group * group_channels) * depth * height * width;
    float sum = 0.0f, sum_sq = 0.0f;

    for (int i = 0; i < inner_size; ++i) {
        float val = group_input[i];
        sum += val;
        sum_sq += val * val;
    }

    sum_shared[outer_idx] = sum;
    sum_sq_shared[outer_idx] = sum_sq;

    __syncthreads();

    float mean = sum_shared[outer_idx] / inner_size;
    float var = sum_sq_shared[outer_idx] / inner_size - mean * mean;
    float inv_std = rsqrtf(var + eps);

    float sum_out = 0.0f;
    for (int i = 0; i < inner_size; ++i) {
        float val = (group_input[i] - mean) * inv_std;
        int channel = group * group_channels + (i / (depth * height * width)) % group_channels;
        val = val * gamma[channel] + beta[channel];
        sum_out += val;
    }

    atomicAdd(&output[batch], sum_out);
}

torch::Tensor fused_group_norm_mean_rocm(torch::Tensor input, int num_groups, torch::Tensor gamma, torch::Tensor beta, float eps) {
    int batch_size = input.size(0);
    auto output = torch::zeros(batch_size, input.options());

    int channels = input.size(1);
    int depth = input.size(2);
    int height = input.size(3);
    int width = input.size(4);

    dim3 grid_dim((batch_size * num_groups + 127) / 128);
    dim3 block_dim(128);
    int shared_size = 2 * batch_size * num_groups * sizeof(float);

    hipLaunchKernelGGL(
        group_norm_mean_kernel,
        grid_dim, block_dim, shared_size, at::cuda::getCurrentHIPStream(),
        input.data_ptr<float>(), output.data_ptr<float>(),
        gamma.data_ptr<float>(), beta.data_ptr<float>(),
        batch_size, channels, depth, height, width,
        num_groups, eps
    );

    output /= (channels * depth * height * width);
    return output;
}

