#include <torch/extension.h>
#include <hip/hip_runtime.h>
#include <ATen/hip/HIPContext.h>

__global__ void fused_min_softmax_kernel(const float* input, float* output, 
    int batch_size, int num_channels, int depth, int height, int width) {

    extern __shared__ float shared_min[];
    int spatial_pos = blockIdx.x;
    int batch = spatial_pos / (height * width);
    int hw_idx = spatial_pos % (height * width);
    int h = hw_idx / width;
    int w = hw_idx % width;
    int c = threadIdx.x;

    if (c >= num_channels) return;

    float min_val = INFINITY;
    for (int d = 0; d < depth; ++d) {
        int idx = batch * num_channels * depth * height * width +
                c * depth * height * width +
                d * height * width +
                h * width +
                w;
        min_val = fminf(min_val, input[idx]);
    }

    shared_min[c] = min_val;
    __syncthreads();

    float max_val = -INFINITY;
    for (int i = 0; i < num_channels; ++i) {
        max_val = fmaxf(max_val, shared_min[i]);
    }

    float exp_sum = 0.0f;
    for (int i = 0; i < num_channels; ++i) {
        exp_sum += expf(shared_min[i] - max_val);
    }

    if (exp_sum < 1e-12) exp_sum = 1e-12;
    int out_idx = batch * num_channels * height * width +
                c * height * width +
                h * width +
                w;
    output[out_idx] = expf(shared_min[c] - max_val) / exp_sum;
}

torch::Tensor fused_min_softmax_rocm(torch::Tensor input) {
    auto sizes = input.sizes();
    int batch_size = sizes[0];
    int num_channels = sizes[1];
    int depth = sizes[2];
    int height = sizes[3];
    int width = sizes[4];

    auto output = torch::zeros({batch_size, num_channels, height, width}, input.options());
    int num_blocks = batch_size * height * width;
    int block_size = num_channels;
    int shared_mem = num_channels * sizeof(float);

    hipLaunchKernelGGL(fused_min_softmax_kernel, 
        num_blocks, block_size, shared_mem, 0,
        input.data_ptr<float>(), output.data_ptr<float>(),
        batch_size, num_channels, depth, height, width);

    return output;
}

