#include <torch/extension.h>
#include <hip/hip_runtime.h>
#include <ATen/hip/HIPContext.h>

__global__ void fused_hardswish_relu_kernel(const float* input, float* output, int size) {
    int idx = blockIdx.x * blockDim.x + threadIdx.x;
    if (idx < size) {
        float x = input[idx];
        float shifted = x + 3.0f;
        float clamped = fmaxf(0.0f, fminf(shifted, 6.0f));
        float hardswish_val = x * clamped / 6.0f;
        output[idx] = fmaxf(hardswish_val, 0.0f);
    }
}

torch::Tensor fused_hardswish_relu_rocm(torch::Tensor x) {
    auto output = torch::zeros_like(x);
    int size = x.numel();
    const int block_size = 256;
    const int num_blocks = (size + block_size - 1) / block_size;
    fused_hardswish_relu_kernel<<<num_blocks, block_size>>>(x.data_ptr<float>(), output.data_ptr<float>(), size);
    return output;
}

