#include <torch/extension.h>
#include <hip/hip_runtime.h>

__global__ void fused_kernel(const float* x, float constant, const float* bias, float scale, float* out, 
                           int elements, int C, int H, int W) {
    int idx = blockIdx.x * blockDim.x + threadIdx.x;
    if (idx < elements) {
        int c = (idx / (H * W)) % C;
        float val = min(x[idx], constant);
        val += bias[c];
        out[idx] = val * scale;
    }
}

torch::Tensor fused_min_add_mul(torch::Tensor x, float constant_val, torch::Tensor bias, float scaling) {
    auto out = torch::empty_like(x);
    int elements = x.numel();
    auto s = x.sizes();
    int C = s[1], H = s[2], W = s[3];

    hipLaunchKernelGGL(fused_kernel, 
        (elements+255)/256, 256, 0, 0,
        x.data_ptr<float>(), constant_val, bias.data_ptr<float>(), scaling,
        out.data_ptr<float>(), elements, C, H, W
    );

    return out;
}

