#include <torch/extension.h>
#include <hip/hip_runtime.h>
#include <ATen/hip/HIPContext.h>

__global__ void fused_scale_bn_kernel(const float* x, const float* scale, const float* bn_weight, const float* bn_bias, float* running_mean, float* running_var, float* y, int batch_size, int out_features, float eps, float momentum, bool training) {
    int j = blockIdx.x;
    int tid = threadIdx.x;
    int stride = blockDim.x;

    extern __shared__ float smem[];
    float* s_sum = smem;
    float* s_sum_sq = smem + blockDim.x;

    if (training) {
        float sum_local = 0.0f, sum_sq_local = 0.0f;

        for (int i = tid; i < batch_size; i += stride) {
            float val = x[i * out_features + j] * scale[j];
            sum_local += val;
            sum_sq_local += val * val;
        }

        s_sum[tid] = sum_local;
        s_sum_sq[tid] = sum_sq_local;
        __syncthreads();

        for (int offset = blockDim.x >> 1; offset > 0; offset >>= 1) {
            if (tid < offset) {
                s_sum[tid] += s_sum[tid + offset];
                s_sum_sq[tid] += s_sum_sq[tid + offset];
            }
            __syncthreads();
        }

        if (tid == 0) {
            float mean = s_sum[0] / batch_size;
            float var = (s_sum_sq[0] / batch_size) - (mean * mean);
            running_mean[j] = running_mean[j] * (1 - momentum) + mean * momentum;
            running_var[j] = running_var[j] * (1 - momentum) + var * momentum;
            s_sum[0] = mean;
            s_sum_sq[0] = var;
        }

        __syncthreads();
        float mean_val = s_sum[0], inv_std = 1.0f / sqrt(s_sum_sq[0] + eps);
        for (int i = tid; i < batch_size; i += stride) {
            float val = x[i * out_features + j] * scale[j];
            y[i * out_features + j] = (val - mean_val) * inv_std * bn_weight[j] + bn_bias[j];
        }
    } else {
        float mean_val = running_mean[j], inv_std = 1.0f / sqrt(running_var[j] + eps);
        for (int i = tid; i < batch_size; i += stride) {
            float val = x[i * out_features + j] * scale[j];
            y[i * out_features + j] = (val - mean_val) * inv_std * bn_weight[j] + bn_bias[j];
        }
    }
}

torch::Tensor fused_scale_bn(torch::Tensor x, torch::Tensor scale, torch::Tensor bn_weight, torch::Tensor bn_bias, torch::Tensor running_mean, torch::Tensor running_var, float eps, float momentum, bool training) {
    TORCH_CHECK(x.dim() == 2, "Input must be 2D");
    int batch_size = x.size(0), out_features = x.size(1);
    auto y = torch::empty_like(x);
    int threads = 256;

    hipLaunchKernelGGL(fused_scale_bn_kernel, dim3(out_features), dim3(threads), 2*threads*sizeof(float), at::hip::getCurrentHIPStream(), 
        x.data_ptr<float>(), scale.data_ptr<float>(), bn_weight.data_ptr<float>(), bn_bias.data_ptr<float>(), 
        running_mean.data_ptr<float>(), running_var.data_ptr<float>(), y.data_ptr<float>(), batch_size, out_features, eps, momentum, training);

    return y;
}

34_ConvTranspose3d_LayerNorm_GELU_Scalin.source:
#include <torch/extension.h>
#include <hip/hip_runtime.h>

__global__ void fused_layernorm_gelu_scaling_kernel(
    const float* input, const float* gamma, const float* beta,
    float* output, float scaling_factor, float eps,
    int N, int C, int D, int H, int W
) {
    int idx = blockIdx.x * blockDim.x + threadIdx.x;
    if (idx >= N * C * D * H * W) return;

    int c = (idx / (D * H * W)) % C;

    float mean = 0.0f;
    float var = 0.0f;
    const float* group_input = input + (idx / W) * W;

    for(int i = 0; i < W; ++i) {
        mean += group_input[i];
    }
    mean /= W;

    for(int i = 0; i < W; ++i) {
        var += (group_input[i] - mean) * (group_input[i] - mean);
    }
    var /= W;

    float x = input[idx];
    float normalized = (x - mean) / sqrt(var + eps);
    float scaled = normalized * gamma[c] + beta[c];
    float gelu = 0.5f * scaled * (1.0f + erff(scaled / 1.41421356237f));
    output[idx] = gelu * scaling_factor;
}

torch::Tensor fused_op_rocm(
    torch::Tensor input, torch::Tensor gamma, torch::Tensor beta,
    float scaling_factor, float eps
) {
    auto out = torch::empty_like(input);
    int num_elements = input.numel();
    const int block_size = 256;
    int grid_size = (num_elements + block_size - 1) / block_size;

    hipLaunchKernelGGL(
        fused_layernorm_gelu_scaling_kernel,
        grid_size, block_size, 0, 0,
        input.data_ptr<float>(), gamma.data_ptr<float>(), beta.data_ptr<float>(),
        out.data_ptr<float>(), scaling_factor, eps,
        input.size(0), input.size(1), input.size(2), input.size(3), input.size(4)
    );
    return out;
}

