#include <torch/extension.h>
#include <hip/hip_runtime.h>
#include <math.h>

__global__ void subtract_hardswish_kernel(const float* input, float subtract_value, float* output, int num_elements) {
    int idx = blockIdx.x * blockDim.x + threadIdx.x;
    if (idx < num_elements) {
        float val = input[idx] - subtract_value;
        float relu6_val = fminf(fmaxf(val + 3.0f, 0.0f), 6.0f);
        output[idx] = val * relu6_val / 6.0f;
    }
}

torch::Tensor subtract_hardswish(torch::Tensor input, float subtract_value) {
    auto num_elements = input.numel();
    auto output = torch::empty_like(input);

    const int block_size = 256;
    int num_blocks = (num_elements + block_size - 1) / block_size;

    hipLaunchKernelGGL(subtract_hardswish_kernel, 
        num_blocks, block_size, 0, 0,
        input.data_ptr<float>(),
        subtract_value,
        output.data_ptr<float>(),
        num_elements
    );

    return output;
}

__global__ void maxpool_mish_kernel(const float* input, float* output, 
    int batches, int channels, int in_h, int in_w, int out_h, int out_w) {

    int out_idx = blockIdx.x * blockDim.x + threadIdx.x;
    int c = blockIdx.y;
    int n = blockIdx.z;

    if (n >= batches || c >= channels) return;

    int ph = (out_idx) / out_w;
    int pw = (out_idx) % out_w;
    if (ph >= out_h || pw >= out_w) return;

    int h_start = ph * 2;
    int h_end = h_start + 2 < in_h ? h_start + 2 : in_h;
    int w_start = pw * 2;
    int w_end = w_start + 2 < in_w ? w_start + 2 : in_w;

    float max_val = -INFINITY;
    for (int h = h_start; h < h_end; ++h) {
        for (int w = w_start; w < w_end; ++w) {
            int inp_idx = ((n * channels + c) * in_h + h) * in_w + w;
            max_val = fmaxf(max_val, input[inp_idx]);
        }
    }

    float softplus = log1pf(expf(max_val));
    float mish = max_val * tanhf(softplus);
    int out_index = ((n * channels + c) * out_h + ph) * out_w + pw;
    output[out_index] = mish;
}

torch::Tensor maxpool_mish(torch::Tensor input) {
    TORCH_CHECK(input.dim() == 4, "Input must be 4D tensor");
    int batches = input.size(0);
    int channels = input.size(1);
    int in_h = input.size(2);
    int in_w = input.size(3);
    int out_h = in_h / 2;
    int out_w = in_w / 2;

    auto output = torch::empty({batches, channels, out_h, out_w}, input.options());

    dim3 threads(256);
    dim3 blocks((out_h * out_w + threads.x - 1) / threads.x, channels, batches);

    hipLaunchKernelGGL(maxpool_mish_kernel, blocks, threads, 0, 0, 
        input.data_ptr<float>(),
        output.data_ptr<float>(),
        batches, channels, in_h, in_w, out_h, out_w
    );

    return output;
}

