#include <torch/extension.h>
#include <hip/hip_runtime.h>
#include <ATen/hip/HIPContext.h>
#include <math.h>

__global__ void fused_clamp_softmax_scale_kernel(
    const float* input,
    float* output,
    float clamp_min,
    float clamp_max,
    float scale,
    int batch_size,
    int channels,
    int depth,
    int height,
    int width) {

    const int total_positions = batch_size * depth * height * width;
    const int idx = blockIdx.x * blockDim.x + threadIdx.x;

    if (idx >= total_positions) return;

    int w = idx % width;
    int i = idx / width;
    int h = i % height;
    i /= height;
    int d = i % depth;
    i /= depth;
    int b = i % batch_size;

    float max_val = -INFINITY;
    for (int c = 0; c < channels; ++c) {
        int input_idx = ((b * channels + c) * depth + d) * height * width + h * width + w;
        float val = input[input_idx];
        val = fminf(clamp_max, fmaxf(clamp_min, val));
        max_val = fmaxf(max_val, val);
    }

    float sum_exp = 0.0f;
    for (int c = 0; c < channels; ++c) {
        int input_idx = ((b * channels + c) * depth + d) * height * width + h * width + w;
        float val = input[input_idx];
        val = fminf(clamp_max, fmaxf(clamp_min, val));
        sum_exp += expf(val - max_val);
    }

    for (int c = 0; c < channels; ++c) {
        int input_idx = ((b * channels + c) * depth + d) * height * width + h * width + w;
        float val = input[input_idx];
        val = fminf(clamp_max, fmaxf(clamp_min, val));
        float exp_val = expf(val - max_val);
        output[input_idx] = (exp_val / sum_exp) * scale;
    }
}

torch::Tensor fused_clamp_softmax_scale_rocm(torch::Tensor input, float clamp_min, float clamp_max, float scale) {
    AT_ASSERTM(input.dim() == 5, "Input tensor must be 5D");
    auto output = torch::empty_like(input);

    int batch_size = input.size(0);
    int channels = input.size(1);
    int depth = input.size(2);
    int height = input.size(3);
    int width = input.size(4);

    int total_positions = batch_size * depth * height * width;
    const int block_size = 256;
    int num_blocks = (total_positions + block_size - 1) / block_size;

    auto stream = at::hip::getCurrentHIPStream();
    fused_clamp_softmax_scale_kernel<<<num_blocks, block_size, 0, stream>>>(
        input.data_ptr<float>(),
        output.data_ptr<float>(),
        clamp_min,
        clamp_max,
        scale,
        batch_size,
        channels,
        depth,
        height,
        width
    );
    return output;
}

40_Matmul_Scaling_ResidualAdd.source:
#include <torch/extension.h>
#include <hip/hip_runtime.h>

__global__ void fused_matmul_scale_add_kernel(
    const float* input,
    const float* weight,
    const float* bias,
    float* output,
    float scaling_factor,
    int batch_size,
    int in_feats,
    int out_feats
) {
    const int row = blockIdx.x * blockDim.x + threadIdx.x;
    const int col = blockIdx.y * blockDim.y + threadIdx.y;

    if (row < batch_size && col < out_feats) {
        float sum = bias[col];
        for (int i = 0; i < in_feats; ++i) {
            sum += input[row * in_feats + i] * weight[col * in_feats + i];
        }
        output[row * out_feats + col] = sum * (1.0f + scaling_factor);
    }
}

torch::Tensor fused_matmul_scale_add_hip(
    torch::Tensor input,
    torch::Tensor weight,
    torch::Tensor bias,
    float scaling_factor
) {
    const int batch_size = input.size(0);
    const int in_feats = input.size(1);
    const int out_feats = weight.size(0);

    auto output = torch::zeros({batch_size, out_feats}, input.options());

    const int TILE = 16;
    dim3 blocks(
        (batch_size + TILE - 1) / TILE,
        (out_feats + TILE - 1) / TILE
    );
    dim3 threads(TILE, TILE);

    hipLaunchKernelGGL(fused_matmul_scale_add_kernel,
        blocks, threads, 0, 0,
        input.data_ptr<float>(),
        weight.data_ptr<float>(),
        bias.data_ptr<float>(),
        output.data_ptr<float>(),
        scaling_factor,
        batch_size,
        in_feats,
        out_feats
    );

    return output;
}

