#include <torch/extension.h>
#include <hip/hip_runtime.h>
#include <ATen/hip/HIPContext.h>
#include <math.h>

__global__ void fused_bn_gelu_kernel(const float* input, const float* gamma, const float* beta,
                                     const float* running_mean, const float* running_var,
                                     float eps, int64_t N, int64_t C, float* output) {
    int idx = blockIdx.x * blockDim.x + threadIdx.x;
    if (idx < N * C) {
        int c = idx % C;
        float x = input[idx];
        float mean = running_mean[c];
        float var = running_var[c];
        float inv_std = 1.0f / sqrtf(var + eps);
        x = (x - mean) * inv_std * gamma[c] + beta[c];
        x *= 0.5f * (1.0f + ::erff(x * 0.7071067811865475f));
        output[idx] = x;
    }
}

torch::Tensor fused_bn_gelu_rocm(torch::Tensor input, torch::Tensor gamma, torch::Tensor beta,
                                torch::Tensor running_mean, torch::Tensor running_var, float eps) {
    auto output = torch::empty_like(input);
    int64_t N = input.size(0);
    int64_t C = input.size(1);
    int64_t num_elements = N * C;

    const int block_size = 256;
    int num_blocks = (num_elements + block_size - 1) / block_size;

    hipLaunchKernelGGL(fused_bn_gelu_kernel,
        dim3(num_blocks), dim3(block_size), 0, at::hip::getCurrentHIPStream(),
        input.data_ptr<float>(),
        gamma.data_ptr<float>(),
        beta.data_ptr<float>(),
        running_mean.data_ptr<float>(),
        running_var.data_ptr<float>(),
        eps,
        N,
        C,
        output.data_ptr<float>());

    return output;
}

