#include <torch/extension.h>
#include <hip/hip_runtime.h>
#include <ATen/hip/HIPContext.h>
#include <cfloat>

__global__ void logsumexp_relu_kernel(const float* input, float* output, int batch_size, int channels,
                                     int depth, int height, int width) {
    int num_spatial = depth * height * width;
    int total_elements = batch_size * num_spatial;

    for (int linear_idx = blockIdx.x * blockDim.x + threadIdx.x;
         linear_idx < total_elements;
         linear_idx += blockDim.x * gridDim.x) {
        int b = linear_idx / num_spatial;
        int spatial_idx = linear_idx % num_spatial;
        int d = spatial_idx / (height * width);
        int remaining = spatial_idx % (height * width);
        int h = remaining / width;
        int w = remaining % width;

        float max_val = -FLT_MAX;
        for (int c = 0; c < channels; ++c) {
            int input_idx = ((b * channels + c) * depth + d) * height * width + h * width + w;
            max_val = fmaxf(max_val, input[input_idx]);
        }

        float sum_exp = 0.0f;
        for (int c = 0; c < channels; ++c) {
            int input_idx = ((b * channels + c) * depth + d) * height * width + h * width + w;
            sum_exp += expf(input[input_idx] - max_val);
        }

        float result = max_val + logf(sum_exp);
        result = fmaxf(result, 0.0f);

        int output_idx = (b * depth * height * width) + (d * height * width) + (h * width) + w;
        output[output_idx] = result;
    }
}

torch::Tensor logsumexp_relu_rocm(torch::Tensor input) {
    auto batch_size = input.size(0);
    auto channels = input.size(1);
    auto depth = input.size(2);
    auto height = input.size(3);
    auto width = input.size(4);

    auto output = torch::zeros({batch_size, 1, depth, height, width}, input.options());

    int total_elements = batch_size * depth * height * width;
    const int block_size = 256;
    int num_blocks = (total_elements + block_size - 1) / block_size;

    hipLaunchKernelGGL(logsumexp_relu_kernel,
        dim3(num_blocks), dim3(block_size), 0, 0,
        input.data_ptr<float>(),
        output.data_ptr<float>(),
        batch_size, channels, depth, height, width
    );

    return output;
}

