49_ConvTranspose3d_Softmax_Sigmoid.source:
#include <torch/extension.h>
#include <hip/hip_runtime.h>
#include <ATen/hip/HIPContext.h>

__global__ void fused_softmax_sigmoid_kernel(const float* input, float* output, int C, int D, int H, int W) {
    int position = blockIdx.x;
    int batch = position / (D * H * W);
    int remainder = position % (D * H * W);
    int d = remainder / (H * W);
    remainder = remainder % (H * W);
    int h = remainder / W;
    int w = remainder % W;

    int c = threadIdx.x;
    if (c >= C) return;

    int input_idx = batch * C * D * H * W 
                    + c * D * H * W 
                    + d * H * W 
                    + h * W 
                    + w;
    float val = input[input_idx];

    extern __shared__ float shared_data[];
    float* s_max = shared_data;
    float* s_sum = shared_data + blockDim.x;

    s_max[c] = val;
    __syncthreads();

    for (int stride = blockDim.x / 2; stride > 0; stride >>= 1) {
        if (c < stride) {
            s_max[c] = fmaxf(s_max[c], s_max[c + stride]);
        }
        __syncthreads();
    }
    float max_val = s_max[0];
    __syncthreads();

    float exp_val = expf(val - max_val);
    s_sum[c] = exp_val;
    __syncthreads();

    for (int stride = blockDim.x / 2; stride > 0; stride >>= 1) {
        if (c < stride) {
            s_sum[c] += s_sum[c + stride];
        }
        __syncthreads();
    }
    float sum_exp = s_sum[0];
    __syncthreads();

    output[input_idx] = 1.0f / (1.0f + expf(-(exp_val / sum_exp)));
}

torch::Tensor fused_softmax_sigmoid_rocm(torch::Tensor x) {
    TORCH_CHECK(x.device().type() == torch::kCUDA, "Input tensor must be on CUDA device");
    auto sizes = x.sizes();
    int C = sizes[1];

    auto output = torch::empty_like(x);
    int batch_size = sizes[0];
    int D = sizes[2];
    int H = sizes[3];
    int W = sizes[4];

    int total_positions = batch_size * D * H * W;
    int block_size = C;
    size_t shared_mem_size = 2 * block_size * sizeof(float);

    hipStream_t stream = at::hip::getCurrentHIPStream();
    fused_softmax_sigmoid_kernel<<<total_positions, block_size, shared_mem_size, stream>>>(
        x.data_ptr<float>(),
        output.data_ptr<float>(),
        C,
        D,
        H,
        W
    );
    return output;
}

