54_Conv2d_Multiply_LeakyReLU_GELU.source:
#include <torch/extension.h>
#include <hip/hip_runtime.h>
#include <ATen/hip/HIPContext.h>
#include <math.h>

__global__ void elementwise_fused_kernel(const float* input, const float* multiplier, float* output, int num_elements, int channels, int height, int width, float negative_slope) {
    int idx = blockIdx.x * blockDim.x + threadIdx.x;

    if (idx >= num_elements) return;

    int total_per_batch = channels * height * width;
    int n = idx / total_per_batch;
    int remaining = idx % total_per_batch;
    int c = remaining / (height * width);

    float x = input[idx];
    float mval = multiplier[c];

    x *= mval;

    x = fmaxf(x, negative_slope * x);

    const float sqrt_2_over_pi = sqrtf(2.0f / 3.14159265358979323846f);
    float x_cubed = x * x * x;
    float tanh_arg = sqrt_2_over_pi * (x + 0.044715f * x_cubed);
    float gelu = 0.5f * x * (1.0f + tanhf(tanh_arg));

    output[idx] = gelu;
}

torch::Tensor elementwise_fused_rocm(torch::Tensor input, torch::Tensor multiplier, float negative_slope) {
    auto output = torch::empty_like(input);
    int num_elements = input.numel();
    int channels = multiplier.size(0);
    int height = input.size(2);
    int width = input.size(3);

    const int block_size = 256;
    dim3 grid((num_elements + block_size - 1) / block_size);

    hipLaunchKernelGGL(elementwise_fused_kernel, grid, block_size, 0, 0, 
        input.data_ptr<float>(), multiplier.data_ptr<float>(), output.data_ptr<float>(),
        num_elements, channels, height, width, negative_slope);

    return output;
}

