#include <torch/extension.h>
#include <hip/hip_runtime.h>
#include <ATen/hip/HIPContext.h>

__global__ void fused_relu_hardswish_kernel(const float* input, float* output, int size) {
    int idx = blockIdx.x * blockDim.x + threadIdx.x;
    if (idx < size) {
        float x = input[idx];
        x = fmaxf(0.0f, x);
        float temp = (x + 3.0f) / 6.0f;
        temp = fminf(temp, 1.0f);
        output[idx] = x * temp;
    }
}

torch::Tensor fused_relu_hardswish_rocm(torch::Tensor input) {
    auto output = torch::empty_like(input);
    int size = input.numel();

    const int block_size = 256;
    const int num_blocks = (size + block_size - 1) / block_size;

    hipLaunchKernelGGL(fused_relu_hardswish_kernel, 
        dim3(num_blocks), 
        dim3(block_size), 
        0, 
        at::hip::getCurrentHIPStream(), 
        input.data_ptr<float>(), 
        output.data_ptr<float>(), 
        size
    );

    return output;
}

