58_ConvTranspose3d_LogSumExp_HardSwish_S.source:
#include <torch/extension.h>
#include <hip/hip_runtime.h>
#include <ATen/hip/HIPContext.h>

#define __shfl_down(var, delta) __shfl_down(var, delta, 64)

template<typename T>
__inline__ __device__ T warpReduceSum(T val) {
    for (int offset = 32; offset > 0; offset /= 2)
        val += __shfl_down(val, offset);
    return val;
}

template<typename T>
__inline__ __device__ T warpReduceMax(T val) {
    for (int offset = 32; offset > 0; offset /= 2)
        val = max(val, __shfl_down(val, offset));
    return val;
}

__global__ void fused_kernel(const float* input, const float* bias,
                             float* output, int B, int C, int D, int H, int W) {
    int b = blockIdx.z;
    int d = blockIdx.y;
    int hw = blockIdx.x;
    int h = hw / W;
    int w = hw % W;
    int c = threadIdx.x;

    if (b >= B || d >= D || h >= H || w >= W || c >= C) return;

    // Calculate input index
    int input_idx = b * C * D * H * W 
                  + c * D * H * W 
                  + d * H * W 
                  + h * W 
                  + w;

    float x = input[input_idx];
    float exp_x = expf(x);

    __shared__ float log_sum_exp;

    // Block-wide sum of exponentials
    float sum_exp = warpReduceSum(exp_x);
    sum_exp += __shfl_down(sum_exp, 16); // For 32 threads/warp, adjust for 16

    if (c == 0) {
        log_sum_exp = logf(sum_exp);
    }
    __syncthreads();

    // Compute v = log_sum_exp * sigmoid(log_sum_exp + 3) /6
    float v = log_sum_exp * (1.0f / (1.0f + expf(-(log_sum_exp + 3.0f)))) / 6.0f;

    // Compute clamped values and find max
    float bias_val = bias[c];
    float u = v - bias_val;
    u = fminf(fmaxf(u, -1.0f), 1.0f);

    // Block-wide max
    float max_u = warpReduceMax(u);
    max_u = max(max_u, __shfl_down(max_u, 16)); // Adjust for 16 channels

    if (c == 0) {
        int output_idx = b * 1 * D * H * W
                       + d * H * W 
                       + h * W 
                       + w;
        output[output_idx] = max_u;
    }
}

torch::Tensor fused_op_rocm(torch::Tensor input, torch::Tensor bias) {
    int B = input.size(0);
    int C = input.size(1);
    int D = input.size(2);
    int H = input.size(3);
    int W = input.size(4);

    auto output = torch::zeros({B, 1, D, H, W}, input.options());

    dim3 blocks(H*W, D, B);
    int channels = C;

    hipLaunchKernelGGL(fused_kernel, 
        dim3(blocks), dim3(channels), 0, at::cuda::getCurrentHIPStream(), 
        input.data_ptr<float>(), 
        bias.data_ptr<float>(), 
        output.data_ptr<float>(), 
        B, C, D, H, W
    );

    return output;
}

