#include <torch/extension.h>
#include <hip/hip_runtime.h>
#include <ATen/hip/HIPContext.h>

__global__ void fused_swish_scale_kernel(const float* input, float* output, float scaling_factor, int size) {
    int idx = blockIdx.x * blockDim.x + threadIdx.x;
    if (idx < size) {
        float x = input[idx];
        float sig = 1.0f / (1.0f + expf(-x));
        output[idx] = x * sig * scaling_factor;
    }
}

torch::Tensor fused_swish_scale_rocm(torch::Tensor input, float scaling_factor) {
    auto output = torch::zeros_like(input);
    int size = input.numel();
    const int block_size = 256;
    int num_blocks = (size + block_size - 1) / block_size;
    hipStream_t stream = at::hip::getCurrentHIPStream();
    fused_swish_scale_kernel<<<num_blocks, block_size, 0, stream>>>(
        input.data_ptr<float>(),
        output.data_ptr<float>(),
        scaling_factor,
        size
    );
    return output;
}

