#include <torch/extension.h>
#include <hip/hip_runtime.h>
#include <ATen/hip/HIPContext.h>

__global__ void fused_sub_tanh_kernel(const float* input, const float* bias, float* output, int batch_size, int out_channels, int height, int width) {
    int index = blockIdx.x * blockDim.x + threadIdx.x;
    int total_elements = batch_size * out_channels * height * width;
    if (index < total_elements) {
        int n = index / (out_channels * height * width);
        int c = (index % (out_channels * height * width)) / (height * width);
        float bias_val = bias[c];
        output[index] = tanhf(input[index] - bias_val);
    }
}

torch::Tensor fused_sub_tanh_rocm(torch::Tensor input, torch::Tensor bias) {
    auto output = torch::zeros_like(input);
    int total_elements = input.numel();
    const int block_size = 256;
    int num_blocks = (total_elements + block_size - 1) / block_size;

    fused_sub_tanh_kernel<<<num_blocks, block_size>>>(input.data_ptr<float>(), bias.data_ptr<float>(), output.data_ptr<float>(), 
        input.size(0), input.size(1), input.size(2), input.size(3));

    return output;
}

