#include <torch/extension.h>
#include <hip/hip_runtime.h>
#include <ATen/hip/HIPContext.h>

__global__ void group_norm_kernel(
    const float* input, float* output,
    const float* weight, const float* bias,
    int n_batch,
    int n_chnls,
    int D, int H, int W,
    int groups, float epsilon) {

    extern __shared__ float smem[];
    int n = blockIdx.x;
    int g = blockIdx.y;
    int C_per_group = n_chnls / groups;
    int c_start = g * C_per_group;
    int c_end = c_start + C_per_group;

    float* sum = smem;
    float* sum_sq = &smem[blockDim.x];

    int tid = threadIdx.x;
    sum[tid] = 0.f;
    sum_sq[tid] = 0.f;

    int elements = C_per_group * D * H * W;
    int elems_per_thread = (elements + blockDim.x - 1) / blockDim.x;
    int start = tid * elems_per_thread;
    int end = min(start + elems_per_thread, elements);

    for(int i=start; i<end; ++i) {
        int c = c_start + (i / (D*H*W)) % C_per_group;
        int d = (i / (H*W)) % D;
        int h = (i / W) % H;
        int w = i % W;
        int idx = ((n * n_chnls + c) * D + d) * H * W + h * W + w;
        float val = input[idx];
        sum[tid] += val;
        sum_sq[tid] += val * val;
    }

    __syncthreads();

    for(int s=blockDim.x/2; s>0; s>>=1) {
        if(tid < s) {
            sum[tid] += sum[tid + s];
            sum_sq[tid] += sum_sq[tid + s];
        }
        __syncthreads();
    }

    float total_sum = sum[0];
    float total_sum_sq = sum_sq[0];
    float mean = total_sum / elements;
    float var = (total_sum_sq / elements) - (mean * mean);
    float inv_std = rsqrtf(var + epsilon);

    for(int i=start; i<end; ++i) {
        int c = c_start + (i / (D*H*W)) % C_per_group;
        int d = (i / (H*W)) % D;
        int h = (i / W) % H;
        int w = i % W;
        int idx = ((n * n_chnls + c) * D + d) * H * W + h * W + w;
        float normalized = (input[idx] - mean) * inv_std;
        output[idx] = normalized * weight[c] + bias[c];
    }
}

torch::Tensor group_norm_rocm(torch::Tensor input, 
                             torch::Tensor weight,
                             torch::Tensor bias,
                             int groups,
                             float epsilon) {
    auto output = torch::empty_like(input);
    auto sizes = input.sizes();
    int n_batch = sizes[0];
    int n_chnls = sizes[1];
    int D = sizes[2], H = sizes[3], W = sizes[4];

    dim3 grid(n_batch, groups);
    dim3 block(256);
    size_t smem = 2 * block.x * sizeof(float);

    hipLaunchKernelGGL(group_norm_kernel, grid, block, smem, at::hip::getCurrentHIPStream(),
        input.data_ptr<float>(),
        output.data_ptr<float>(),
        weight.data_ptr<float>(),
        bias.data_ptr<float>(),
        n_batch, n_chnls, D, H, W, groups, epsilon);

    return output;
}

62_Matmul_GroupNorm_LeakyReLU_Sum.source:
#include <torch/extension.h>
#include <hip/hip_runtime.h>
#include <ATen/hip/HIPContext.h>

__global__ void fused_kernel(const float* input, float* output, const float* weight, const float* bias,
                             int N, int C, int G, float eps, float slope, float scale) {
    extern __shared__ float smem[];
    float* s_sum = smem;
    float* s_sqsum = s_sum + blockDim.x;

    int n = blockIdx.x;
    int g = blockIdx.y;
    int c_start = g * (C/G);
    int c_end = c_start + (C/G);
    int tid = threadIdx.x;

    float sum = 0.0f, sqsum = 0.0f;
    for (int c = c_start + tid; c < c_end; c += blockDim.x) {
        float val = input[n*C + c];
        sum += val;
        sqsum += val * val;
    }
    s_sum[tid] = sum;
    s_sqsum[tid] = sqsum;
    __syncthreads();

    for (int stride=blockDim.x/2; stride>0; stride>>=1) {
        if (tid < stride) {
            s_sum[tid] += s_sum[tid+stride];
            s_sqsum[tid] += s_sqsum[tid+stride];
        }
        __syncthreads();
    }

    if (tid == 0) {
        float mean = s_sum[0] / (C/G);
        float var = (s_sqsum[0]/(C/G) - mean*mean) + eps;
        float inv_std = rsqrtf(var);
        s_sum[0] = mean;
        s_sqsum[0] = inv_std * scale;
    }
    __syncthreads();

    float inv_std_scaled = s_sqsum[0];
    for (int c = c_start + tid; c < c_end; c += blockDim.x) {
        float x = input[n*C + c];
        float norm = (x - s_sum[0]) * inv_std_scaled * weight[c] + bias[c];
        output[n*C + c] = (norm > 0) ? norm : norm * slope;
    }
}

torch::Tensor fused_op(torch::Tensor x, torch::Tensor w, torch::Tensor b, 
                      int groups, float eps, float slope, float scale) {
    auto out = torch::empty_like(x);
    int N = x.size(0);
    int C = x.size(1);
    dim3 grid(N, groups);
    int block = 256;
    size_t smem = 2 * block * sizeof(float);
    fused_kernel<<<grid, block, smem>>>(
        x.data_ptr<float>(), out.data_ptr<float>(), 
        w.data_ptr<float>(), b.data_ptr<float>(),
        N, C, groups, eps, slope, scale
    );
    return out;
}

63_Gemm_ReLU_Divide.source:
#include <torch/extension.h>
#include <hip/hip_runtime.h>
#include <ATen/hip/HIPContext.h>

__global__ void fused_linear_relu_scale_kernel(const float* x, const float* w, const float* b, float* out, 
                                               int batch_size, int in_features, int out_features, float multiplier) {
    int row = blockIdx.x * blockDim.x + threadIdx.x;
    int col = blockIdx.y * blockDim.y + threadIdx.y;

    if (row >= batch_size || col >= out_features) return;

    float sum = 0.0f;
    for(int k = 0; k < in_features; ++k) {
        sum += x[row * in_features + k] * w[col * in_features + k];
    }

    sum += b[col];
    sum = fmaxf(sum, 0.0f) * multiplier;
    out[row * out_features + col] = sum;
}

torch::Tensor fused_linear_relu_scale_rocm(torch::Tensor x, torch::Tensor w, torch::Tensor b, float divider) {
    auto options = torch::TensorOptions().device(x.device()).dtype(x.dtype());
    auto out = torch::zeros({x.size(0), w.size(0)}, options);

    dim3 threads(16, 16);
    dim3 blocks(
        (x.size(0) + threads.x - 1) / threads.x,
        (w.size(0) + threads.y - 1) / threads.y
    );

    hipLaunchKernelGGL(fused_linear_relu_scale_kernel, 
        blocks, threads, 0, 0, 
        x.data_ptr<float>(),
        w.data_ptr<float>(),
        b.data_ptr<float>(),
        out.data_ptr<float>(),
        x.size(0),
        x.size(1),
        w.size(0),
        1.0f / divider
    );

    return out;
}

63_Gemm_ReLU_Divide.class_model:
class ModelNew(nn.Module):
    def __init__(self, in_features, out_features, divisor):
        super(ModelNew, self).__init__()
        self.in_features = in_features
        self.out_features = out_features
        self.divisor = divisor

        self.weight = nn.Parameter(torch.Tensor(out_features, in_features))
        self.bias = nn.Parameter(torch.Tensor(out_features))

        nn.init.kaiming_uniform_(self.weight, a=math.sqrt(5))
        bound = 1 / math.sqrt(in_features) if in_features > 0 else 0
        nn.init.uniform_(self.bias, -bound, bound)

    def forward(self, x):
        return fused_linear_ops.fused_linear_relu_scale_rocm(x, self.weight, self.bias, self.divisor)

64_Gemm_LogSumExp_LeakyReLU_LeakyReLU_GE.source:
#include <torch/extension.h>
#include <hip/hip_runtime.h>
#include <ATen/hip/HIPContext.h>
#include <math.h>

__global__ void fused_act_kernel(const float* input, float* output, int size) {
    int idx = blockIdx.x * blockDim.x + threadIdx.x;
    if (idx < size) {
        float x = input[idx];
        x = fmaxf(0.01f * x, x);
        x = fmaxf(0.01f * x, x);
        const float kSqrtTwoOverPi = 0.7978845608028654f;
        float inner = x + 0.044715f * x * x * x;
        float gelu_x = 0.5f * x * (1.0f + tanhf(kSqrtTwoOverPi * inner));
        inner = gelu_x + 0.044715f * gelu_x * gelu_x * gelu_x;
        gelu_x = 0.5f * gelu_x * (1.0f + tanhf(kSqrtTwoOverPi * inner));
        output[idx] = gelu_x;
    }
}

torch::Tensor fused_activations_rocm(torch::Tensor x) {
    auto output = torch::empty_like(x);
    int size = x.numel();
    const int block_size = 256;
    int num_blocks = (size + block_size - 1) / block_size;
    hipLaunchKernelGGL(fused_act_kernel, 
        dim3(num_blocks), dim3(block_size), 0, 0, 
        x.data_ptr<float>(), 
        output.data_ptr<float>(), 
        size
    );
    return output;
}

