class ModelNew(nn.Module):
    def __init__(self, in_features, out_features, dropout_p):
        super().__init__()
        self.weight = nn.Parameter(torch.randn(out_features, in_features))
        self.bias = nn.Parameter(torch.zeros(out_features))
        self.dropout_p = dropout_p

        nn.init.kaiming_uniform_(self.weight, a=5**0.5)
        bound = (1 / in_features)**0.5
        nn.init.uniform_(self.bias, -bound, bound)

    def forward(self, x):
        B = x.size(0)
        out_features = self.weight.size(0)

        if self.training:
            mask = (torch.rand(B, out_features, device=x.device) > self.dropout_p).float() 
            mask *= (1/(1 - self.dropout_p))
        else:
            mask = torch.ones(B, out_features, device=x.device)

        x = custom_ops.fused_matmul_dropout(x, self.weight, self.bias, mask)
        return custom_ops.mean_softmax(x)

67_Conv2d_GELU_GlobalAvgPool.source:
#include <torch/extension.h>
#include <hip/hip_runtime.h>
#include <ATen/hip/HIPContext.h>

#define HIP_CHECK(err)                                                         \\
    do {                                                                       \\
        hipError_t err_ = (err);                                               \\
        if (err_ != hipSuccess) {                                              \\
            fprintf(stderr, "HIP error %d at %s:%d\\n", err_, __FILE__, __LINE__); \\
            exit(1);                                                           \\
        }                                                                      \\
    } while (0)

__global__ void fused_gelu_pool_kernel(const float* input, float* output, int H, int W, int B, int C) {
    int batch = blockIdx.x;
    int channel = blockIdx.y;

    if (batch >= B || channel >= C) return;

    extern __shared__ float shared[];

    int num_elements = H * W;
    int start_offset = batch * C * H * W + channel * H * W;

    float thread_sum = 0.0f;
    for (int idx = threadIdx.x; idx < num_elements; idx += blockDim.x) {
        float x_val = input[start_offset + idx];
        const float sqrt_2_over_pi = 0.7978845608028654f;
        const float coff = 0.044715f;
        float x_cubed = x_val * x_val * x_val;
        float inner = sqrt_2_over_pi * (x_val + coff * x_cubed);
        float gelu = 0.5f * x_val * (1.0f + tanhf(inner));
        thread_sum += gelu;
    }

    shared[threadIdx.x] = thread_sum;
    __syncthreads();

    for (int stride = blockDim.x / 2; stride > 0; stride >>= 1) {
        if (threadIdx.x < stride) {
            shared[threadIdx.x] += shared[threadIdx.x + stride];
        }
        __syncthreads();
    }

    if (threadIdx.x == 0) {
        output[batch * C + channel] = shared[0] / num_elements;
    }
}

torch::Tensor fused_gelu_pool_rocm(torch::Tensor input) {
    TORCH_CHECK(input.dim() == 4, "Input must be 4D");
    TORCH_CHECK(input.is_cuda(), "Input must be a CUDA tensor");

    auto contiguous_input = input.contiguous();
    int B = contiguous_input.size(0);
    int C = contiguous_input.size(1);
    int H = contiguous_input.size(2);
    int W = contiguous_input.size(3);

    auto output = torch::zeros({B, C}, contiguous_input.options());

    int block_size = 256;
    dim3 grid(B, C);
    size_t shared_mem = block_size * sizeof(float);

    hipLaunchKernelGGL(fused_gelu_pool_kernel, grid, block_size, shared_mem, 0,
        contiguous_input.data_ptr<float>(), output.data_ptr<float>(), H, W, B, C);
    HIP_CHECK(hipGetLastError());
    HIP_CHECK(hipDeviceSynchronize());

    return output;
}

