#include <torch/extension.h>
#include <hip/hip_runtime.h>

__global__ void fused_avg_pool_kernel(
    const float* input,
    float* output,
    int D_out,
    int H_out,
    int W_out,
    int D_in,
    int H_in,
    int W_in,
    int batch_size,
    int channels
) {
    int idx = blockIdx.x * blockDim.x + threadIdx.x;
    int total_out_elements = batch_size * channels * D_out * H_out * W_out;
    if (idx >= total_out_elements) return;

    int b = idx / (channels * D_out * H_out * W_out);
    int rem = idx % (channels * D_out * H_out * W_out);
    int c = rem / (D_out * H_out * W_out);
    rem = rem % (D_out * H_out * W_out);
    int d_out = rem / (H_out * W_out);
    rem = rem % (H_out * W_out);
    int h_out = rem / W_out;
    int w_out = rem % W_out;

    int d_start = d_out * 4;
    int d_end = d_start + 4;
    int h_start = h_out * 4;
    int h_end = h_start + 4;
    int w_start = w_out * 4;
    int w_end = w_start + 4;

    d_end = min(d_end, D_in);
    h_end = min(h_end, H_in);
    w_end = min(w_end, W_in);

    float sum = 0.0f;
    int count = 0;
    for (int d = d_start; d < d_end; ++d) {
        for (int h = h_start; h < h_end; ++h) {
            for (int w = w_start; w < w_end; ++w) {
                int input_idx = b * channels * D_in * H_in * W_in +
                                c * D_in * H_in * W_in +
                                d * H_in * W_in +
                                h * W_in +
                                w;
                sum += input[input_idx];
                count++;
            }
        }
    }

    output[idx] = count > 0 ? sum / count : 0.0f;
}

torch::Tensor fused_avg_pool_rocm(torch::Tensor input) {
    auto batch_size = input.size(0);
    auto channels = input.size(1);
    auto D_in = input.size(2);
    auto H_in = input.size(3);
    auto W_in = input.size(4);

    int D_out = D_in / 4;
    int H_out = H_in / 4;
    int W_out = W_in / 4;

    auto output = torch::zeros({batch_size, channels, D_out, H_out, W_out}, input.options());

    int total_elements = batch_size * channels * D_out * H_out * W_out;
    const int block_size = 256;
    int num_blocks = (total_elements + block_size - 1) / block_size;

    hipLaunchKernelGGL(
        fused_avg_pool_kernel,
        num_blocks, block_size, 0, 0,
        input.data_ptr<float>(), output.data_ptr<float>(),
        D_out, H_out, W_out, D_in, H_in, W_in,
        batch_size, channels
    );

    return output;
}

73_Conv2d_BatchNorm_Scaling.source:
#include <torch/extension.h>
#include <hip/hip_runtime.h>
#include <ATen/hip/HIPContext.h>

__global__ void fused_bn_scaling_kernel(const float* input, const float* a, const float* b, float* output, int N, int C, int H, int W) {
    int idx = blockIdx.x * blockDim.x + threadIdx.x;
    int total_elements = N * C * H * W;
    if (idx >= total_elements) return;

    int c = (idx / (H * W)) % C;
    output[idx] = input[idx] * a[c] + b[c];
}

torch::Tensor fused_bn_scaling_rocm(torch::Tensor input, torch::Tensor a, torch::Tensor b) {
    auto output = torch::empty_like(input);
    auto sizes = input.sizes();
    int N = sizes[0], C = sizes[1], H = sizes[2], W = sizes[3];
    int num_elements = input.numel();

    const int block_size = 256;
    int num_blocks = (num_elements + block_size - 1) / block_size;

    hipLaunchKernelGGL(fused_bn_scaling_kernel, num_blocks, block_size, 0, 0, 
        input.data_ptr<float>(), 
        a.data_ptr<float>(), 
        b.data_ptr<float>(), 
        output.data_ptr<float>(),
        N, C, H, W
    );

    return output;
}

73_Conv2d_BatchNorm_Scaling.class_model:
class ModelNew(nn.Module):
    def __init__(self, in_channels, out_channels, kernel_size, scaling_factor):
        super(ModelNew, self).__init__()
        self.conv = nn.Conv2d(in_channels, out_channels, kernel_size)
        self.bn = nn.BatchNorm2d(out_channels)
        self.scaling_factor = scaling_factor

    def forward(self, x):
        x = self.conv(x)

        if self.training:
            mean = x.mean(dim=(0,2,3))
            var = x.var(dim=(0,2,3), unbiased=False)
            with torch.no_grad():
                self.bn.running_mean = (1 - self.bn.momentum) * self.bn.running_mean + self.bn.momentum * mean
                self.bn.running_var = (1 - self.bn.momentum) * self.bn.running_var + self.bn.momentum * var
        else:
            mean = self.bn.running_mean
            var = self.bn.running_var

        gamma = self.bn.weight
        beta = self.bn.bias
        eps = self.bn.eps

        a = (gamma * self.scaling_factor) / torch.sqrt(var + eps)
        b = (beta * self.scaling_factor) - (mean * gamma * self.scaling_factor) / torch.sqrt(var + eps)

        return fused_bn_scaling.fused_bn_scaling_rocm(x.contiguous(), a.contiguous(), b.contiguous())

