#include <torch/extension.h>
#include <hip/hip_runtime.h>
#include <ATen/hip/HIPContext.h>

__global__ void fused_leaky_multiplier_kernel(const float* x, const float* multiplier, float* out, 
                                              int B, int C, int D, int H, int W, float leaky_slope, 
                                              int total_elements) {
    int idx = blockIdx.x * blockDim.x + threadIdx.x;
    if (idx >= total_elements) return;

    int elements_per_channel = D * H * W;
    int index_in_batch = idx % (C * elements_per_channel);
    int c = index_in_batch / elements_per_channel;

    float val = x[idx];
    val = val > 0 ? val : val * leaky_slope;
    val *= multiplier[c];
    val = val > 0 ? val : val * leaky_slope;
    out[idx] = val;
}

torch::Tensor fused_leaky_multiplier_rocm(torch::Tensor x, torch::Tensor multiplier, double leaky_slope) {
    TORCH_CHECK(x.dim() == 5, "x must be 5D (N, C, D, H, W)");
    TORCH_CHECK(multiplier.device() == x.device(), "multiplier must be on the same device as x");
    TORCH_CHECK(multiplier.dim() == 4, "multiplier must be 4D (C, 1, 1, 1)");
    TORCH_CHECK(multiplier.size(0) == x.size(1), "multiplier size must match x's channel count");

    auto out = torch::zeros_like(x);
    int total_elements = x.numel();
    float leaky_slope_float = static_cast<float>(leaky_slope);
    int B = x.size(0);
    int C = x.size(1);
    int D = x.size(2);
    int H = x.size(3);
    int W = x.size(4);

    const int block_size = 256;
    int num_blocks = (total_elements + block_size - 1) / block_size;
    hipStream_t stream = at::hip::getCurrentHIPStream();

    hipLaunchKernelGGL(fused_leaky_multiplier_kernel,
        dim3(num_blocks),
        dim3(block_size),
        0,
        stream,
        x.data_ptr<float>(),
        multiplier.data_ptr<float>(),
        out.data_ptr<float>(),
        B, C, D, H, W,
        leaky_slope_float,
        total_elements
    );

    return out;
}

