81_Gemm_Swish_Divide_Clamp_Tanh_Clamp.source:
#include <torch/extension.h>
#include <hip/hip_runtime.h>
#include <ATen/hip/HIPContext.h>

__global__ void fused_post_gemm_kernel(const float* input, float* output, int num_elements) {
    int idx = blockIdx.x * blockDim.x + threadIdx.x;
    if (idx < num_elements) {
        float x = input[idx];
        float swish = x * (1.0f / (1.0f + expf(-x)));
        swish /= 2.0f;
        swish = fmaxf(fminf(swish, 1.0f), -1.0f);
        float tanh_val = tanhf(swish);
        output[idx] = fmaxf(fminf(tanh_val, 1.0f), -1.0f);
    }
}

torch::Tensor fused_post_gemm_rocm(torch::Tensor input) {
    auto output = torch::empty_like(input);
    int num_elements = input.numel();
    const int block_size = 256;
    int grid_size = (num_elements + block_size - 1) / block_size;

    fused_post_gemm_kernel<<<grid_size, block_size>>>(
        input.data_ptr<float>(), output.data_ptr<float>(), num_elements);

    return output;
}

