88_Gemm_GroupNorm_Swish_Multiply_Swish.source:
#include <torch/extension.h>
#include <hip/hip_runtime.h>
#include <ATen/hip/HIPContext.h>

__global__ void group_norm_swish_kernel(
    const float* input, const float* gamma, const float* beta,
    float* output, int batch_size, int num_features, int num_groups, float eps) {

    extern __shared__ float shared_data[];
    float* shared_sum = shared_data;
    float* shared_sum_sq = &shared_data[blockDim.x];

    int group_id = blockIdx.x % num_groups;
    int sample_id = blockIdx.x / num_groups;
    int channels_per_group = num_features / num_groups;

    int channel_start = group_id * channels_per_group;
    int idx = sample_id * num_features + channel_start;

    float thread_sum = 0.0f;
    float thread_sum_sq = 0.0f;

    for (int i = threadIdx.x; i < channels_per_group; i += blockDim.x) {
        float val = input[idx + i];
        thread_sum += val;
        thread_sum_sq += val * val;
    }

    shared_sum[threadIdx.x] = thread_sum;
    shared_sum_sq[threadIdx.x] = thread_sum_sq;
    __syncthreads();

    for (int s = blockDim.x/2; s>0; s>>=1) {
        if (threadIdx.x < s) {
            shared_sum[threadIdx.x] += shared_sum[threadIdx.x + s];
            shared_sum_sq[threadIdx.x] += shared_sum_sq[threadIdx.x + s];
        }
        __syncthreads();
    }

    float mean = shared_sum[0] / channels_per_group;
    float var = (shared_sum_sq[0] / channels_per_group) - (mean * mean);
    float inv_std = rsqrtf(var + eps);

    for (int i = threadIdx.x; i < channels_per_group; i += blockDim.x) {
        int pos = idx + i;
        float x = (input[pos] - mean) * inv_std;
        x = x * gamma[channel_start + i] + beta[channel_start + i];
        x *= 1.0f / (1.0f + expf(-x));
        output[pos] = x;
    }
}

torch::Tensor fused_group_norm_swish_rocm(torch::Tensor input, torch::Tensor gamma, torch::Tensor beta, int num_groups, float eps) {
    auto output = torch::empty_like(input);
    int batch_size = input.size(0);
    int num_features = input.size(1);

    dim3 grid(batch_size * num_groups);
    dim3 block(256);
    size_t shared_mem = 2 * block.x * sizeof(float);

    group_norm_swish_kernel<<<grid, block, shared_mem>>>(
        input.data_ptr<float>(), gamma.data_ptr<float>(), beta.data_ptr<float>(),
        output.data_ptr<float>(), batch_size, num_features, num_groups, eps);

    return output;
}

