#include <torch/extension.h>
#include <hip/hip_runtime.h>
#include <ATen/hip/HIPContext.h>

__global__ void fused_ops_kernel(const float* input, float add_val, float mult_val, float* output, int numel) {
    int idx = blockIdx.x * blockDim.x + threadIdx.x;
    if (idx < numel) {
        float val = input[idx] + add_val;
        val = fminf(val, 0.0f);
        val = 0.5f * val * (1.0f + tanhf(0.7978845608028654f * (val + 0.044715f * val * val * val)));
        output[idx] = val * mult_val;
    }
}

torch::Tensor fused_ops_rocm(torch::Tensor x, float add_value, float multiply_value) {
    auto output = torch::zeros_like(x);
    int numel = x.numel();
    const int block_size = 256;
    int grid_size = (numel + block_size - 1) / block_size;

    hipLaunchKernelGGL(fused_ops_kernel, 
        grid_size, block_size, 0, at::cuda::getCurrentHIPStream(), 
        x.data_ptr<float>(), add_value, multiply_value, output.data_ptr<float>(), numel);

    return output;
}

