#include <torch/extension.h>
#include <hip/hip_runtime.h>

__global__ void fused_bias_hardtanh_mish_kernel(
    const float* input,
    const float* bias,
    float* output,
    int num_elements,
    int feature_size,
    float min_val,
    float max_val) {

    int idx = blockIdx.x * blockDim.x + threadIdx.x;
    if (idx < num_elements) {
        int bias_idx = idx % feature_size;
        float val = input[idx] + bias[bias_idx];
        val = fmaxf(min_val, fminf(max_val, val));
        float softplus_val = log1pf(expf(val));
        output[idx] = val * tanhf(softplus_val);
    }
}

torch::Tensor fused_bias_hardtanh_mish_rocm(
    torch::Tensor input,
    torch::Tensor bias,
    int feature_size,
    float min_val,
    float max_val) {

    auto num_elements = input.numel();
    auto output = torch::empty_like(input);

    const int block_size = 256;
    const int grid_size = (num_elements + block_size - 1) / block_size;

    hipLaunchKernelGGL(fused_bias_hardtanh_mish_kernel, 
        dim3(grid_size), dim3(block_size), 0, 0,
        input.data_ptr<float>(),
        bias.data_ptr<float>(),
        output.data_ptr<float>(),
        num_elements,
        feature_size,
        min_val,
        max_val
    );

    return output;
}

95_Matmul_Add_Swish_Tanh_GELU_Hardtanh.source:
#include <torch/extension.h>
#include <hip/hip_runtime.h>
#include <ATen/hip/HIPContext.h>
#include <cmath>

__global__ void fused_act_kernel(const float* x, const float* add_vec, float* out, int out_features, int total) {
    int idx = blockIdx.x * blockDim.x + threadIdx.x;
    if (idx >= total) return;

    int j = idx % out_features;
    float v = x[idx] + add_vec[j];

    // Swish
    v *= 1.0f / (1.0f + expf(-v));

    // Tanh
    v = tanhf(v);

    // GELU approx
    v = 0.5f * v * (1.0f + tanhf(0.7978845608028654f * (v + 0.044715f * v*v*v)));

    // Hardtanh
    out[idx] = fminf(fmaxf(v, -1.0f), 1.0f);
}

torch::Tensor fused_activation_rocm(torch::Tensor x, torch::Tensor add_vec) {
    TORCH_CHECK(x.is_cuda() && add_vec.is_cuda(), "Tensors must be on GPU");
    TORCH_CHECK(x.is_contiguous() && add_vec.is_contiguous(), "Requires contiguous tensors");
    TORCH_CHECK(x.dim() == 2, "x must be 2D");
    TORCH_CHECK(add_vec.dim() == 1, "add_vec must be 1D");
    TORCH_CHECK(x.size(1) == add_vec.size(0), "Dimension mismatch");

    auto out = torch::empty_like(x);
    int total = x.numel();
    int out_feat = x.size(1);

    int block = 256;
    int grid = (total + block - 1) / block;

    hipStream_t stream = at::hip::getCurrentHIPStream().stream();
    fused_act_kernel<<<grid, block, 0, stream>>>(
        x.data_ptr<float>(), add_vec.data_ptr<float>(), 
        out.data_ptr<float>(), out_feat, total
    );

    return out;
}

