#include <torch/extension.h>
#include <hip/hip_runtime.h>
#include <ATen/hip/HIPContext.h>

__global__ void fused_matmul_avgpool_kernel(const float* x, const float* weight, const float* bias, float* output, int batch_size, int in_features, int out_features, int pool_size) {
    const int pooled_out = out_features / pool_size;
    const int idx = blockIdx.x * blockDim.x + threadIdx.x;
    const int b = idx / pooled_out;
    const int j = idx % pooled_out;

    if (b >= batch_size || j >= pooled_out) return;

    float sum_val = 0.0f;

    for (int k = 0; k < pool_size; ++k) {
        const int row = j * pool_size + k;
        if (row >= out_features) break;

        float dot = 0.0f;
        for (int d = 0; d < in_features; ++d) {
            dot += x[b * in_features + d] * weight[row * in_features + d];
        }
        dot += bias[row];
        sum_val += dot;
    }

    sum_val /= pool_size;

    output[b * pooled_out + j] = sum_val;
}

torch::Tensor fused_matmul_avgpool_rocm(torch::Tensor x, torch::Tensor weight, torch::Tensor bias, int pool_size) {
    TORCH_CHECK(x.dim() == 2, "Expected x to be 2-dimensional");
    const int batch_size = x.size(0);
    const int in_features = x.size(1);
    const int out_features = weight.size(0);
    const int pooled_out = out_features / pool_size;

    auto output = torch::zeros({batch_size, pooled_out}, x.options());

    const int total_threads = batch_size * pooled_out;
    const int block_size = 256;
    const int num_blocks = (total_threads + block_size - 1) / block_size;

    hipLaunchKernelGGL(fused_matmul_avgpool_kernel,
        dim3(num_blocks), dim3(block_size), 0, at::hip::getCurrentHIPStream(),
        x.data_ptr<float>(), weight.data_ptr<float>(), bias.data_ptr<float>(), output.data_ptr<float>(),
        batch_size, in_features, out_features, pool_size
    );

    return output;
}

99_Matmul_GELU_Softmax.source:
#include <torch/extension.h>
#include <hip/hip_runtime.h>
#include <ATen/hip/HIPContext.h>

__global__ void fused_gelu_softmax_kernel(const float* input, float* output, int rows, int cols) {
    extern __shared__ float shared_mem[];
    float* shared_gelu = shared_mem;
    float* shared_max = &shared_mem[cols];

    int tid = threadIdx.x;
    int row = blockIdx.x;

    if (row >= rows) return;

    const float* row_input = input + row * cols;
    float* row_output = output + row * cols;

    for (int idx = tid; idx < cols; idx += blockDim.x) {
        float x = row_input[idx];
        float gelu = 0.5f * x * (1.0f + tanhf(0.797884560802865f * (x + 0.044715f * x * x * x)));
        shared_gelu[idx] = gelu;
    }
    __syncthreads();

    float local_max = -INFINITY;
    for (int idx = tid; idx < cols; idx += blockDim.x) {
        local_max = fmaxf(local_max, shared_gelu[idx]);
    }
    shared_max[tid] = local_max;
    __syncthreads();

    for (int stride = blockDim.x/2; stride>0; stride>>=1) {
        if (tid < stride) {
            shared_max[tid] = fmaxf(shared_max[tid], shared_max[tid + stride]);
        }
        __syncthreads();
    }

    float max_val = shared_max[0];
    __syncthreads();

    float local_sum = 0.0f;
    for (int idx = tid; idx < cols; idx += blockDim.x) {
        float val = shared_gelu[idx] - max_val;
        float exp_val = expf(val);
        shared_gelu[idx] = exp_val;
        local_sum += exp_val;
    }

    shared_max[tid] = local_sum;
    __syncthreads();

    for (int stride = blockDim.x/2; stride>0; stride>>=1) {
        if (tid < stride) {
            shared_max[tid] += shared_max[tid + stride];
        }
        __syncthreads();
    }

    float sum_exp = shared_max[0];
    float inv_sum = 1.0f / sum_exp;

    for (int idx = tid; idx < cols; idx += blockDim.x) {
        row_output[idx] = shared_gelu[idx] * inv_sum;
    }
}

torch::Tensor fused_gelu_softmax_rocm(torch::Tensor input) {
    auto output = torch::empty_like(input);
    int rows = input.size(0);
    int cols = input.size(1);

    dim3 grid(rows);
    int block_size = 256;
    dim3 block(block_size);
    size_t shared_size = (cols + block_size) * sizeof(float);

    hipLaunchKernelGGL(
        fused_gelu_softmax_kernel,
        grid, block, shared_size, at::hip::getCurrentHIPStream(),
        input.data_ptr<float>(), output.data_ptr<float>(), rows, cols
    );

    return output;
}

