#include <torch/extension.h>
#include <hip/hip_runtime.h>
#include <ATen/hip/HIPContext.h>

__global__ void concat_features_kernel(
    const float* input,
    float* output,
    int current_ch,
    int growth_rate,
    int batch_size,
    int input_ch,
    int output_ch,
    int height,
    int width
) {
    int idx = blockIdx.x * blockDim.x + threadIdx.x;
    int spatial = height * width;
    int ch_per_sample = input_ch;
    int output_offset = current_ch * spatial;

    if (idx < batch_size * growth_rate * spatial) {
        int pos = idx / (growth_rate * spatial);
        int rem = idx % (growth_rate * spatial);
        int c = rem / spatial;
        int s = rem % spatial;

        output += pos * output_ch * spatial + output_offset + c * spatial + s;
        *output = input[idx];
    }
}

void dense_concat(
    torch::Tensor input,
    torch::Tensor output,
    int current_ch,
    int growth_rate
) {
    int batch_size = input.size(0);
    int in_ch = input.size(1);
    int height = input.size(2);
    int width = input.size(3);
    int spatial = height * width;
    int elements = batch_size * growth_rate * spatial;

    const int block_size = 256;
    int num_blocks = (elements + block_size - 1) / block_size;

    hipLaunchKernelGGL(
        concat_features_kernel,
        dim3(num_blocks),
        dim3(block_size),
        0,
        at::hip::getCurrentHIPStream(),
        input.data_ptr<float>(),
        output.data_ptr<float>(),
        current_ch,
        growth_rate,
        batch_size,
        in_ch,
        output.size(1),
        height,
        width
    );
}

