#include <torch/extension.h>
#include <hip/hip_runtime.h>
#include <math.h>

__global__ void fused_mlp_kernel(const float* input, const float* w1, const float* b1, 
                                const float* w2, const float* b2, float* output, 
                                int B_total, int C, int H, int D) {
    int global_idx = blockIdx.x * blockDim.x + threadIdx.x;
    if (global_idx >= B_total * D) return;

    int batch_seq = global_idx / D;
    int d_idx = global_idx % D;

    float hidden = b2[d_idx];
    for (int h=0; h<H; ++h) {
        float sum = b1[h];
        for (int c=0; c<C; ++c) {
            sum += input[batch_seq*C + c] * w1[c*H + h];
        }
        sum = fmaxf(sum, 0.0f);
        hidden += sum * w2[h*D + d_idx];
    }
    output[global_idx] = hidden;
}

torch::Tensor fused_mlp_rocm(torch::Tensor x, torch::Tensor w1, torch::Tensor b1, 
                            torch::Tensor w2, torch::Tensor b2) {
    int B_total = x.size(0);
    int C = x.size(1); 
    int H = b1.size(0);
    int D = b2.size(0);

    auto y = torch::zeros({B_total, D}, x.options());
    const int block_size = 256;
    int grid_size = (B_total * D + block_size - 1) / block_size;

    fused_mlp_kernel<<<grid_size, block_size>>>(
        x.data_ptr<float>(), w1.data_ptr<float>(), b1.data_ptr<float>(),
        w2.data_ptr<float>(), b2.data_ptr<float>(), y.data_ptr<float>(),
        B_total, C, H, D
    );
    return y;
}

32_ConvolutionalVisionTransformer.class_model:
class ModelNew(nn.Module):
    def __init__(self, num_classes, embed_dim=512, num_heads=8, num_layers=6, 
                 mlp_ratio=4.0, patch_size=4, in_channels=3):
        super().__init__()
        self.patch_size = patch_size
        self.conv1 = nn.Conv2d(in_channels, embed_dim, kernel_size=patch_size, stride=patch_size)
        self.linear_proj = nn.Linear(embed_dim * (32//patch_size)**2, embed_dim)
        self.cls_token = nn.Parameter(torch.zeros(1, 1, embed_dim))
        self.transformer_layers = nn.ModuleList([
            CustomTransformerLayer(embed_dim, num_heads, int(embed_dim*mlp_ratio)) 
            for _ in range(num_layers)
        ])
        self.fc_out = nn.Linear(embed_dim, num_classes)

    def forward(self, x):
        B = x.shape[0]
        x = self.conv1(x).flatten(2).transpose(1, 2)  # (B, num_patches, embed_dim)
        x = self.linear_proj(x.flatten(1))  # (B, embed_dim)

        cls_token = self.cls_token.expand(B, -1, -1)
        x = torch.cat([cls_token, x.unsqueeze(1)], dim=1)

        for layer in self.transformer_layers:
            x = layer(x)

        return self.fc_out(x[:, 0])

