#include <torch/extension.h>
#include <hip/hip_runtime.h>

__global__ void fused_i2h_kernel(
    const float* x, const float* hidden_prev,
    const float* weight, const float* bias,
    float* hidden_new,
    int batch_size, int input_size, int hidden_size) {

    int tid = blockIdx.x * blockDim.x + threadIdx.x;
    if (tid >= batch_size * hidden_size) return;

    int b = tid / hidden_size;
    int j = tid % hidden_size;

    const float* weight_row = weight + j * (input_size + hidden_size);
    const float* x_row = x + b * input_size;
    const float* hidden_row = hidden_prev + b * hidden_size;

    float sum = 0.0f;
    for (int k = 0; k < input_size; ++k)
        sum += x_row[k] * weight_row[k];

    for (int l = 0; l < hidden_size; ++l)
        sum += hidden_row[l] * weight_row[input_size + l];

    sum += bias[j];
    hidden_new[tid] = tanhf(sum);
}

torch::Tensor fused_i2h_rocm(
    torch::Tensor x,
    torch::Tensor hidden_prev,
    torch::Tensor weight,
    torch::Tensor bias,
    int input_size,
    int hidden_size) {

    int batch_size = x.size(0);
    auto hidden_new = torch::zeros({batch_size, hidden_size}, x.options());

    int size = batch_size * hidden_size;
    const int block_size = 256;
    int num_blocks = (size + block_size - 1) / block_size;

    hipLaunchKernelGGL(
        fused_i2h_kernel,
        dim3(num_blocks),
        dim3(block_size),
        0,
        0,
        x.data_ptr<float>(),
        hidden_prev.data_ptr<float>(),
        weight.data_ptr<float>(),
        bias.data_ptr<float>(),
        hidden_new.data_ptr<float>(),
        batch_size,
        input_size,
        hidden_size);

    return hidden_new;
}

