#include <torch/extension.h>
#include <hip/hip_runtime.h>
#include <ATen/hip/HIPContext.h>

__global__ void fused_add_relu_kernel(const float* a, const float* b, float* out, int size) {
    int idx = blockIdx.x * blockDim.x + threadIdx.x;
    if (idx < size) {
        float sum = a[idx] + b[idx];
        out[idx] = fmaxf(sum, 0.0f);
    }
}

torch::Tensor fused_add_relu_rocm(torch::Tensor a, torch::Tensor b) {
    auto out = torch::empty_like(a);
    int size = a.numel();

    const int block_size = 256;
    int num_blocks = (size + block_size - 1) / block_size;

    hipStream_t stream = at::hip::getCurrentHIPStream();
    fused_add_relu_kernel<<<num_blocks, block_size, 0, stream>>>(
        a.data_ptr<float>(), 
        b.data_ptr<float>(), 
        out.data_ptr<float>(), 
        size
    );

    return out;
}
